INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l17',2,3,17,'Always young','青春常驻','must 的用法(主考:must 表不可逃避的义务 = have to / have got to 三者可互换 · 跟 will 用 have to · must 无过去式,过去用 had to · must 表推测''一定是''must be)+ as 的多义与 in spite of(辅考:as = 因为/当…时/作为 · in spite of + 名词表''尽管'')','姑姑詹妮弗是位演员,至少三十五岁却总在台上扮演小姑娘——演出时必须穿鲜红连衣裙和黑长筒袜,去年还不得不穿短袜;被问年龄时她只笑答''长大成人一定很可怕''','{"q":"Listen and answer — Why doesn''t Aunt Jennifer tell anyone how old she is?","options":["Because she thinks it must be terrible to be grown up","Because she has forgotten her real age","Because she is exactly seventeen","Because nobody ever asks her"],"answer_index":0}'::jsonb,'{"title":"说\"必须/不得不\"(must 和 have to)","intro":"本课讲怎么说\"必须做某事\"——must 和 have to。注意:两者意思相近、常可互换;但 must 没有过去式,过去的\"必须\"要用 had to;must 还能表示\"一定是\"(推测)。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["must 表\"不可逃避的必须\",= have to / have got to","She must appear in a red dress. = She has to appear…"],["跟 will 说将来的\"必须\":用 have to,不用 must","Jennifer will have to take part in a new play."],["must 没有过去式,过去的\"必须\"用 had to","Last year she had to wear short socks."],["must 还能表\"一定是\"(有把握的推测)","She must be at least thirty-five years old."]]},"specialRules":[{"rule":"问句里问\"必须吗\"常用 have to:Must you go? = Do you have to go?","mark":"疑问互换"},{"rule":"as 有多种含义:因为(as I am busy)/当…时(as I was leaving)/作为(as an engineer)","mark":"as 多义"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',1,NULL,'My aunt Jennifer is an actress.','我的姑姑詹妮弗是位演员。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',2,NULL,'She must be at least thirty-five years old.','她少说也有三十五岁了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',3,NULL,'In spite of this, she often appears on the stage as a young girl.','尽管如此,她却常在台上扮演小姑娘。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',4,NULL,'Every evening she goes to the theater and becomes someone new.','每天晚上她去剧院,变成一个全新的角色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',5,NULL,'Jennifer will have to take part in a new play soon.','詹妮弗很快又要参加一部新剧的演出。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',6,NULL,'This time, she will play a girl of seventeen.','这一次,她将扮演一个十七岁的少女。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',7,NULL,'In the play, she must appear in a bright red dress and long black stockings.','演出时她必须穿一条鲜红的连衣裙和黑色的长筒袜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',8,NULL,'Last year, in another play, she had to wear short socks and a bright, orange-colored dress.','去年演另一部剧时,她不得不穿短袜和一件鲜艳的橘红色连衣裙。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',9,NULL,'Jennifer never tells anyone her real age.','詹妮弗从不告诉任何人她的真实年龄。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l17',10,NULL,'If anyone ever asks her how old she is, she always laughs and answers, ''Darling, it must be terrible to be grown up!''','一旦有人问起她的年龄,她总是笑着回答:"亲爱的,长大成人一定很可怕吧!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
