INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l17','take part in','',NULL,'/teɪk pɑːrt ɪn/','Jennifer will take part in a new play.','詹妮弗将参加一部新剧的演出。','Many students took part in the contest.','许多学生参加了比赛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l17','in spite of','',NULL,'/ɪn spaɪt əv/','In spite of this, she plays young girls.','尽管如此,她仍扮演小姑娘。','In spite of the rain, we went out.','尽管下着雨,我们还是出门了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l17','grow up','',NULL,'/ɡroʊ ʌp/','It must be terrible to be grown up.','长大成人一定很可怕。','She grew up in a small town.','她在一个小镇长大。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l17','at least','',NULL,'/ət liːst/','She must be at least thirty-five.','她至少有三十五岁了。','It takes at least an hour.','这至少要花一个小时。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp1','choice','{"stem":"must 常常用来表示什么?","options":["此刻正在做的事","不可逃避的义务(必须)","将来可能发生的事","过去做过的事"],"answer_index":1,"explanation_cn":"must 常用来表示一种不可逃避的必须,说话人觉得没有选择余地。✓ She must appear in a red dress."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp1','choice','{"stem":"\"She ___ appear in a bright red dress.\"(表义务:必须穿)","options":["musts","musting","must","must to"],"answer_index":2,"stem_cn":"她必须穿一条鲜红的连衣裙登台。","explanation_cn":"表\"必须\"用 must,后面直接跟动词原形 appear。must 本身不加 -s、也不加 to。✓ She must appear in a bright red dress."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp1','choice','{"stem":"\"I ___ finish my homework tonight.\"(表义务:必须)","options":["must to","must","am must","musts"],"answer_index":1,"stem_cn":"我今晚必须完成作业。","explanation_cn":"表\"必须\"用 must + 动词原形 finish。没有 musts、must to、musting 这些形式。✓ I must finish my homework tonight."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp2','choice','{"stem":"must 表\"必须\"时,可以用哪个短语替换?","options":["have to / have got to","used to","want to","would like to"],"answer_index":0,"explanation_cn":"must 表\"必须\"时,可以用 have to 或 have got to 替换,意思一样。✓ I must go = I have to go = I have got to go."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp2','choice','{"stem":"\"He must leave now.\" 与它意思相同的是:","options":["He may leave now.","He has to leave now.","He might leave now.","He can leave now."],"answer_index":1,"explanation_cn":"must 表\"必须\",和 have to 同义,所以 He must leave now = He has to leave now。may/can/might 是\"可以 / 也许\",意思不同。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp3','choice','{"stem":"\"Jennifer will ___ take part in a new play.\"(将来的\"必须\":must 没有将来式)","options":["musts","must","have to","have got"],"answer_index":2,"stem_cn":"詹妮弗将不得不参加一部新剧的演出。","explanation_cn":"跟在 will 后面说将来的\"必须\",要用 have to(will have to);must 没有将来式,不能说 will must。✓ Jennifer will have to take part in a new play."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp3','choice','{"stem":"\"Must you go now?\" 用 have to 提问,同样意思:","options":["You have to go now?","Do you must go now?","Have you to go now?","Do you have to go now?"],"answer_index":3,"explanation_cn":"问\"必须…吗\"时常改用 have to:Must you go? = Do you have to go? 用 do 帮忙提问,不能说 Do you must。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp4','choice','{"stem":"must 表\"必须\"时,它的过去表达是:","options":["must-ed","had to","did must","musted"],"answer_index":1,"explanation_cn":"must 没有过去式,过去的\"必须\"用 had to;musted、did must 都不存在。✓ Yesterday she had to leave early."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp4','choice','{"stem":"\"Last year she ___ wear short socks.\"(去年:过去的\"必须\")","options":["must","have to","musted","had to"],"answer_index":3,"stem_cn":"去年她不得不穿短袜。","explanation_cn":"Last year(去年)是过去,过去的\"必须\"用 had to,不能用 must(它没有过去式)。✓ Last year she had to wear short socks."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp5','choice','{"stem":"must 除了表\"必须\",还能表示什么?","options":["热情的邀请","客气的请求","有把握的推测(\"一定是…\")","随口的建议"],"answer_index":2,"explanation_cn":"must 除了\"必须\",还能表示很有把握的推测\"一定是\"。✓ She must be at least thirty-five."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp5','choice','{"stem":"\"She ___ be at least thirty-five.\"(有把握的推测:一定有)","options":["must","may","might","could"],"answer_index":0,"stem_cn":"她一定有至少三十五岁了。","explanation_cn":"\"一定有三十五岁\"是很有把握的推测,用 must be。may/might/could 是\"也许\",把握没那么大。✓ She must be at least thirty-five."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp6','choice','{"stem":"\"It ___ be terrible to be grown up!\"(说话人很肯定的推测)","options":["would","may","can","must"],"answer_index":3,"stem_cn":"长大成人一定很可怕!","explanation_cn":"说话人对\"长大成人很可怕\"很确定,用 must be 表强推测。may/can/would 语气弱或意思不对。✓ It must be terrible to be grown up."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp6','choice','{"stem":"\"Yesterday I ___ work late.\"(昨天:过去的\"不得不\")","options":["had to","musted","must","have to"],"answer_index":0,"stem_cn":"昨天我不得不加班到很晚。","explanation_cn":"Yesterday(昨天)是过去,过去的\"不得不\"用 had to,不用 must。✓ Yesterday I had to work late."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp7','choice','{"stem":"\"I cannot come, ___ I am busy.\"(表原因:因为我忙)","options":["or","but","as","so"],"answer_index":2,"stem_cn":"我不能来,因为我很忙。","explanation_cn":"as 可以表原因,相当于 because。✓ I cannot come, as I am busy(因为我忙)。so / or / but 逻辑不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp7','choice','{"stem":"在 \"He works as an engineer\" 里,as 的意思是:","options":["因为","正如","当…的时候","作为,担任"],"answer_index":3,"explanation_cn":"work as + 职业 = 担任、以…身份工作。✓ He works as an engineer,他做工程师的工作。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp7','choice','{"stem":"在 \"As I was leaving, the phone rang\" 里,as 的意思是:","options":["当…的时候","但是","作为","因为"],"answer_index":0,"explanation_cn":"as 在这里表\"当…的时候\",相当于 when。✓ As I was leaving, the phone rang,我正要离开时电话响了。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp8','choice','{"stem":"in spite of 的意思是\"尽管\",它后面接的是:","options":["一个动词原形","一个形容词","一个完整的句子","名词 / 动名词"],"answer_index":3,"explanation_cn":"in spite of 意思是\"尽管\",后面接名词或动名词,不接完整句子。✓ in spite of the rain / in spite of being tired."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',5,'am2_l17_gp8','choice','{"stem":"\"___ the rain, they went out.\"(尽管下雨,后面接名词 the rain)","options":["In spite of","Though","Because","Although"],"answer_index":0,"stem_cn":"尽管下着雨,他们还是出门了。","explanation_cn":"后面直接跟名词 the rain,用 In spite of(尽管)。though / although / because 后面要接完整句子,不能只跟一个名词。✓ In spite of the rain, they went out."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"美语\"颜色\"拼作:","options":["colar","colour","color","collor"],"answer_index":2,"explanation_cn":"美语\"颜色\"拼 color(-or 结尾);英式拼 colour。✓ an orange-colored dress."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"美语\"剧院\"拼作:","options":["theatre","theator","teater","theater"],"answer_index":3,"explanation_cn":"美语\"剧院\"拼 theater(-er 结尾);英式拼 theatre。✓ She goes to the theater."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"take part in 的意思是:","options":["观看","参加","负责","离开"],"answer_index":1,"explanation_cn":"take part in = 参加(某活动)。✓ take part in a new play,参加一部新剧。\n顺带记:离开 = leave;观看 = watch;负责 = be in charge of."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"in spite of 的意思是:","options":["尽管","为了","因为","除了"],"answer_index":0,"explanation_cn":"in spite of = 尽管、不顾。✓ In spite of this, she plays young girls,尽管如此,她仍演小姑娘。\n顺带记:因为 = because of;为了 = for;除了 = except for."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"grow up 的意思是:","options":["培育庄稼","站起来","长大成人","变老"],"answer_index":2,"explanation_cn":"grow up = 长大、长大成人。✓ It must be terrible to be grown up,长大成人一定很可怕。\n顺带记:变老 = grow old;站起来 = stand up;培育庄稼 = grow crops."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',6,NULL,'choice','{"stem":"at least 的意思是:","options":["至多","正好","大约","至少"],"answer_index":3,"explanation_cn":"at least = 至少、起码。✓ She must be at least thirty-five,她至少三十五岁。\n顺带记:至多 = at most;大约 = about;正好 = exactly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',7,NULL,'cloze','{"stem":"第 1 空","context":"My aunt Jennifer is an actress. She ___1___ be at least thirty-five years old. Jennifer will ___2___ take part in a new play soon. Last year she ___3___ wear short socks. It ___4___ be terrible to be grown up!","blank_no":1,"options":["must","may","can","should"],"answer_index":0,"explanation_cn":"\"至少三十五岁\"是很有把握的推测\"一定是\",用 must be。✓ She must be at least thirty-five.\n✗ may:may 是\"也许\",把握不够,这里是很肯定的推测;✗ can:can 不表这种\"一定是\"的推测;✗ should:should 是\"应该\",不是\"一定是\"."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',7,NULL,'cloze','{"stem":"第 2 空","context":"My aunt Jennifer is an actress. She ___1___ be at least thirty-five years old. Jennifer will ___2___ take part in a new play soon. Last year she ___3___ wear short socks. It ___4___ be terrible to be grown up!","blank_no":2,"options":["have to","must","has to","musted"],"answer_index":0,"explanation_cn":"跟在 will 后面说将来的\"必须\",用 have to → will have to。✓ Jennifer will have to take part.\n✗ must:must 没有将来式,不能说 will must;✗ has to:will 后面跟原形 have,不用 has;✗ musted:根本没有这个词."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',7,NULL,'cloze','{"stem":"第 3 空","context":"My aunt Jennifer is an actress. She ___1___ be at least thirty-five years old. Jennifer will ___2___ take part in a new play soon. Last year she ___3___ wear short socks. It ___4___ be terrible to be grown up!","blank_no":3,"options":["had to","must","has to","have to"],"answer_index":0,"explanation_cn":"Last year(去年)是过去,过去的\"必须\"用 had to。✓ Last year she had to wear short socks.\n✗ must:must 没有过去式,表示不了\"去年\";✗ has to:has to 是现在,不是过去;✗ have to:have to 也是现在,和\"去年\"对不上."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',7,NULL,'cloze','{"stem":"第 4 空","context":"My aunt Jennifer is an actress. She ___1___ be at least thirty-five years old. Jennifer will ___2___ take part in a new play soon. Last year she ___3___ wear short socks. It ___4___ be terrible to be grown up!","blank_no":4,"options":["must","has to","may","should"],"answer_index":0,"explanation_cn":"说话人对\"长大成人很可怕\"很确定,用 must be 表强推测。✓ It must be terrible.\n✗ has to:这里是\"一定是\"的推测,不是\"不得不\";✗ may:may 是\"也许\",语气太弱;✗ should:should 是\"应该\",不是\"一定是\"."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',8,NULL,'choice','{"stem":"What is Aunt Jennifer''s job?","options":["She is a teacher","She is a nurse","She is an actress","She is a singer"],"answer_index":2,"explanation_cn":"课文开头说 My aunt Jennifer is an actress,詹妮弗是位女演员。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',8,NULL,'choice','{"stem":"How old must Jennifer be at least?","options":["At least thirty-five","About seventeen","Under twenty","Exactly forty"],"answer_index":0,"explanation_cn":"课文说 She must be at least thirty-five years old,她少说也有三十五岁。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',8,NULL,'choice','{"stem":"What must Jennifer wear in the new play?","options":["A raincoat and boots","A blue coat and white socks","A school uniform","A bright red dress and long black stockings"],"answer_index":3,"explanation_cn":"课文说 she must appear in a bright red dress and long black stockings,新剧里她要穿鲜红连衣裙和黑长筒袜。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',9,NULL,'choice','{"stem":"你想说\"我现在必须走了\"(表义务):","options":["I leave now must.","I must leave now.","I am must leave now.","I must to leave now."],"answer_index":1,"explanation_cn":"说\"现在必须走\",用 must 加动词 leave。✓ I must leave now. 场合:有急事要马上离开时说。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',9,NULL,'choice','{"stem":"你想说\"他一定很累\"(有把握的推测):","options":["He must very tired.","He is must tired.","He musts be tired.","He must be very tired."],"answer_index":3,"explanation_cn":"说\"他一定很累\",是很有把握的推测,用 must be。✓ He must be very tired. 场合:看到别人忙了一整天时说。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',9,NULL,'choice','{"stem":"你想说\"昨天我不得不早起\"(过去的\"必须\"用 had to):","options":["Yesterday I had to get up early.","Yesterday I have to got up early.","Yesterday I must to get up early.","Yesterday I must get up early."],"answer_index":0,"explanation_cn":"\"昨天\"是过去,过去的\"不得不\"用 had to。✓ Yesterday I had to get up early. 场合:解释昨天为什么起得那么早。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"appear 的意思是:","options":["登台;出现","购买","休息","消失"],"answer_index":0,"explanation_cn":"appear = 登台、出现。✓ She often appears on the stage,她常登台。\n顺带记:消失 = disappear;购买 = buy;休息 = rest."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"stocking 的意思是:","options":["手套","短袜","长筒袜","帽子"],"answer_index":2,"explanation_cn":"stocking = (女用)长筒袜。✓ long black stockings,黑色长筒袜。\n顺带记:短袜 = sock;帽子 = hat;手套 = glove."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"\"She ___ be very rich; look at her car.\"(有把握的推测:一定)","options":["can","may","should","must"],"answer_index":3,"stem_cn":"她一定很有钱,看看她的车。","explanation_cn":"\"一定很有钱\"是很有把握的推测,用 must be。✓ She must be very rich. may / can / should 语气或意思不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"\"Last night I ___ study for the test.\"(过去的\"不得不\")","options":["had to","musted","have to","must"],"answer_index":0,"stem_cn":"昨晚我不得不为考试复习。","explanation_cn":"Last night(昨晚)是过去,过去的\"不得不\"用 had to。✓ Last night I had to study for the test."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"\"You must be joking!\" 这句话的意思是:","options":["你必须讲个笑话!","你一定是在开玩笑吧!","你会开玩笑。","你不许开玩笑!"],"answer_index":1,"explanation_cn":"You must be joking! 这里 must 是\"一定是\"的推测,意思是\"你一定是在开玩笑吧\"。场合:听到难以置信的话时说。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"朋友说 \"I have to go now.\",意思最接近:","options":["我想再待一会儿","我不想走","我现在必须走了","我可以走了"],"answer_index":2,"explanation_cn":"I have to go now = 我现在必须走了,have to 表示\"必须、不得不\"。场合:该离开时礼貌地说明。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"In the new play, how old will Jennifer''s character be?","options":["Forty","Thirty-five","Seven","Seventeen"],"answer_index":3,"passage":"My aunt Jennifer is an actress. She must be at least thirty-five years old. In spite of this, she often appears on the stage as a young girl. Every evening she goes to the theater and becomes someone new. Jennifer will have to take part in a new play soon. This time, she will play a girl of seventeen. In the play, she must appear in a bright red dress and long black stockings. Last year, in another play, she had to wear short socks and a bright, orange-colored dress. Jennifer never tells anyone her real age. If anyone ever asks her how old she is, she always laughs and answers, ''Darling, it must be terrible to be grown up!''","explanation_cn":"课文说 This time, she will play a girl of seventeen,新剧里她演十七岁的少女。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"What did Jennifer have to wear in last year''s play?","options":["A red dress and black stockings","A school uniform","Short socks and an orange-colored dress","A long white coat"],"answer_index":2,"passage":"My aunt Jennifer is an actress. She must be at least thirty-five years old. In spite of this, she often appears on the stage as a young girl. Every evening she goes to the theater and becomes someone new. Jennifer will have to take part in a new play soon. This time, she will play a girl of seventeen. In the play, she must appear in a bright red dress and long black stockings. Last year, in another play, she had to wear short socks and a bright, orange-colored dress. Jennifer never tells anyone her real age. If anyone ever asks her how old she is, she always laughs and answers, ''Darling, it must be terrible to be grown up!''","explanation_cn":"课文说 Last year she had to wear short socks and a bright, orange-colored dress,去年她穿的是短袜和橘红色连衣裙。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"What does Jennifer answer when people ask her age?","options":["''Please ask my mother.''","''Darling, it must be terrible to be grown up!''","''I never act.''","''I am seventeen.''"],"answer_index":1,"audio":"My aunt Jennifer is an actress. She must be at least thirty-five years old. In spite of this, she often appears on the stage as a young girl. Every evening she goes to the theater and becomes someone new. Jennifer will have to take part in a new play soon. This time, she will play a girl of seventeen. In the play, she must appear in a bright red dress and long black stockings. Last year, in another play, she had to wear short socks and a bright, orange-colored dress. Jennifer never tells anyone her real age. If anyone ever asks her how old she is, she always laughs and answers, ''Darling, it must be terrible to be grown up!''","explanation_cn":"课文结尾她总是回答 ''Darling, it must be terrible to be grown up!''"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l17',10,NULL,'choice','{"stem":"Does Jennifer tell people her real age?","options":["Only on the stage","Yes, she tells everyone","No, she never tells anyone","Only to children"],"answer_index":2,"audio":"My aunt Jennifer is an actress. She must be at least thirty-five years old. In spite of this, she often appears on the stage as a young girl. Every evening she goes to the theater and becomes someone new. Jennifer will have to take part in a new play soon. This time, she will play a girl of seventeen. In the play, she must appear in a bright red dress and long black stockings. Last year, in another play, she had to wear short socks and a bright, orange-colored dress. Jennifer never tells anyone her real age. If anyone ever asks her how old she is, she always laughs and answers, ''Darling, it must be terrible to be grown up!''","explanation_cn":"课文说 Jennifer never tells anyone her real age,她从不告诉别人真实年龄。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l18',2,3,18,'He often does this!','他经常干这种事!','过去完成时(主考:had + 过去分词表''过去的过去''——在另一个过去动作之前就已完成 · 常与 after/before/by the time 连用 · 否定 hadn''t、疑问把 had 提前)+ have 的用法/give 短语动词/beside vs besides(辅考:have = 拥有 = have got · give back 归还/give up 放弃/give in 屈服 · beside 在旁边≠besides 除…之外)','在乡村小餐馆吃完午饭却找不到提包、付不了账——原来是店主的狗把包叼到院子里去了,''他经常干这种事!''','{"q":"Listen and answer — What had happened to the writer''s bag?","options":["The owner''s dog had taken it into the yard","A thief had stolen it on the street","The writer had left it at home","It had fallen into the river"],"answer_index":0}'::jsonb,'{"title":"说''过去的过去''(过去完成时 had + 过去分词)","intro":"本课讲怎么表示''在过去某件事之前就已经完成''的动作——过去完成时。构成:had + 过去分词(不分人称都用 had)。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["过去完成时 = had + 过去分词(不分人称都用 had)","I had left it on a chair beside the door."],["表''过去的过去'':比另一个过去动作更早完成","After I had had lunch, I looked for my bag."],["常和 after / before / by the time 连用分先后","By the time I looked, his dog had taken the bag."],["否定用 hadn''t;疑问把 had 提前","Had his dog taken it? / It hadn''t done this before."]]},"specialRules":[{"rule":"have 表''拥有''时 = have got:He has a dog = He has got a dog","mark":"have=拥有"},{"rule":"give 短语:give back 归还 / give up 放弃 / give in 屈服","mark":"give 短语"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',1,NULL,'After I had had lunch at a village café, I looked for my bag.','我在一家乡村小餐馆吃过午饭后,就找我的提包。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',2,NULL,'I had left it on a chair beside the door, and now it wasn''t there!','我原先把它放在门边的椅子上,可这会儿却不见了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',3,NULL,'As I was looking for it, the owner came in.','我正找着的时候,店主走了进来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',4,NULL,'''Did you enjoy your meal?'' he asked.','"您用餐还满意吗?"他问道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',5,NULL,'''Yes, thank you,'' I answered, ''but I can''t pay the check. I don''t have my bag.''','"很好,谢谢,"我回答,"可我付不了账,我的提包不见了。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',6,NULL,'The owner smiled and immediately went out.','店主笑了笑,马上走了出去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',7,NULL,'In a few minutes, he came back with my bag and gave it back to me.','几分钟后,他拿着我的提包回来,把它还给了我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',8,NULL,'''I''m very sorry,'' he said.','"实在抱歉,"他说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',9,NULL,'''My dog had taken it into the yard.''','"我的狗把它叼到院子里去了。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l18',10,NULL,'''He often does this!''','"他经常干这种事!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
