INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp1','choice','{"stem":"过去完成时(表''过去的过去'')的构成是:","options":["had + 过去分词","will + 动词原形","have/has + 过去分词","is/are + 动词-ing"],"answer_index":0,"explanation_cn":"过去完成时 = had + 过去分词,不分人称都用 had。它表示\"过去的过去\"。✓ I had left it on a chair beside the door."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp1','choice','{"stem":"\"By the time I arrived, the train ___ left.\"(我到之前火车就已开走)","options":["left","was leaving","has left","had left"],"answer_index":3,"stem_cn":"我到达时,火车已经开走了。","explanation_cn":"\"我到之前火车就开走了\",\"开走\"比\"到达\"更早,先发生的用过去完成 had left。✓ By the time I arrived, the train had left."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp1','choice','{"stem":"\"When I saw her, she ___ already finished her work.\"(我看到她之前就已完成)","options":["had","was","did","has"],"answer_index":0,"stem_cn":"我见到她时,她已经完成了工作。","explanation_cn":"\"完成工作\"比\"我看到她\"更早,先发生用过去完成 had finished(这里填 had)。✓ When I saw her, she had already finished her work."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp2','choice','{"stem":"过去完成时用来表示:","options":["将来要做的事","在过去某个动作''之前''就已完成的事","此刻正在做的事","经常反复的习惯"],"answer_index":1,"explanation_cn":"过去完成时表示\"过去的过去\"——在另一个过去动作之前就已经完成的事。✓ After I had had lunch, I looked for my bag."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp2','choice','{"stem":"\"After I ___ had lunch, I looked for my bag.\"(先吃完午饭,再找包)","options":["has","have","was","had"],"answer_index":3,"stem_cn":"我吃完午饭后,就去找我的包。","explanation_cn":"After 引导先发生的\"吃午饭\",用过去完成 had had(第一个 had 帮忙构成时态,第二个 had 是 have 的过去分词)。✓ After I had had lunch, I looked for my bag."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp2','choice','{"stem":"\"He told me he ___ seen the movie before.\"(他说他之前已看过)","options":["has","had","have","did"],"answer_index":1,"stem_cn":"他告诉我他以前看过这部电影。","explanation_cn":"\"看电影\"发生在\"他告诉我\"之前,先发生用过去完成 had seen。✓ He told me he had seen the movie before."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp3','choice','{"stem":"\"By the time the owner came in, his dog ___ taken the bag.\"(老板进来前狗已叼走)","options":["has","have","had","was"],"answer_index":2,"stem_cn":"老板进来时,他的狗已经把包叼走了。","explanation_cn":"\"狗叼走包\"在\"老板进来\"之前,先发生用过去完成 had taken。✓ By the time the owner came in, his dog had taken the bag."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp3','choice','{"stem":"两件都发生在过去的事,先发生的那件用:","options":["过去完成时(had + 过去分词)","一般现在时","现在进行时","一般将来时"],"answer_index":0,"explanation_cn":"两件过去的事,先发生的那件用过去完成时,后发生的用一般过去时。✓ After he had gone, I called him."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp4','choice','{"stem":"过去完成时的否定式是:","options":["don''t + 动词原形","hadn''t + 过去分词","haven''t + 过去分词","wasn''t + 动词-ing"],"answer_index":1,"explanation_cn":"过去完成时的否定 = hadn''t(had not)+ 过去分词。✓ It hadn''t done this before."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp4','choice','{"stem":"\"___ his dog taken the bag before he came in?\"(过去完成的疑问:助动词提前)","options":["Had","Has","Was","Did"],"answer_index":0,"stem_cn":"他进来之前,他的狗已经把包叼走了吗?","explanation_cn":"过去完成的疑问句,把 had 提到主语前面。✓ Had his dog taken the bag before he came in?"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp5','choice','{"stem":"have 表示''拥有''时,可以换成:","options":["have been","have got","have done","have gone"],"answer_index":1,"explanation_cn":"have 表\"拥有\"时可换成 have got,意思一样。✓ He has a dog = He has got a dog."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp5','choice','{"stem":"\"He has a big house.\" 与它意思相同的是:","options":["He does got a big house.","He is got a big house.","He has getting a big house.","He has got a big house."],"answer_index":3,"explanation_cn":"have 表\"拥有\"= have got,所以 He has a big house = He has got a big house。其他几个形式都不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp6','choice','{"stem":"\"I ___ a bath before dinner.\"(晚饭前洗了个澡,have 作''洗、进行''讲)","options":["had","was having got","have got","had got"],"answer_index":0,"stem_cn":"我在晚饭前洗了个澡。","explanation_cn":"have a bath = 洗澡(have 作\"进行、经历\"讲),过去用 had a bath;这种 have 不能加 got。✓ I had a bath before dinner."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp6','choice','{"stem":"下面哪个说法''不能''用 have got 替换?","options":["have money(有钱)","have a house(有房子)","have a good time(玩得开心)","have a car(有辆车)"],"answer_index":2,"explanation_cn":"have a good time 里的 have 是\"度过、进行\",不能说 have got a good time;而 have a car / money / house 是\"拥有\",可以用 have got。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp7','choice','{"stem":"give back 的意思是:","options":["归还","放弃","赠送","屈服"],"answer_index":0,"explanation_cn":"give back = 归还、还回。✓ He gave the bag back to me,他把包还给了我。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp7','choice','{"stem":"\"Don''t ___! You can still win.\"(别放弃,表示''放弃'')","options":["give back","give in","give up","give away"],"answer_index":2,"stem_cn":"别放弃!你还能赢。","explanation_cn":"give up = 放弃、别再坚持。✓ Don''t give up! give back 是归还、give in 是屈服、give away 是赠送,都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp8','choice','{"stem":"beside 和 besides 的区别是:","options":["beside=在…旁边;besides=除…之外","beside=除…之外;besides=在旁边","两个都表示''反对''","两个意思完全一样"],"answer_index":0,"explanation_cn":"beside 是\"在…旁边\";besides 是\"除…之外(还)\"。别把这两个词搞混。✓ sit beside me / besides English, he speaks French."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',5,'am2_l18_gp8','choice','{"stem":"\"Come and sit ___ me.\"(坐到我旁边:在…旁边)","options":["besides","beside","between","among"],"answer_index":1,"stem_cn":"过来坐在我旁边。","explanation_cn":"\"坐在我旁边\"用 beside(在…旁边)。besides 是\"除…之外\",between / among 是\"在…之间\",都不对。✓ Come and sit beside me."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"美语餐馆里\"账单\"常说:","options":["bill","check","note","paper"],"answer_index":1,"explanation_cn":"美语在餐馆里把\"账单\"叫 check;英式叫 bill。✓ Can I have the check, please? 结账时这么说。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"give back 的意思是:","options":["归还","赠送","放弃","屈服"],"answer_index":0,"explanation_cn":"give back = 归还、还回去。✓ He gave it back to me,他把它还给了我。\n顺带记:放弃 = give up;赠送 = give away;屈服 = give in."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"give up 的意思是:","options":["归还","放弃;戒掉","赠送","举起"],"answer_index":1,"explanation_cn":"give up = 放弃;也指戒掉(烟酒等)。✓ Don''t give up! 别放弃!\n顺带记:归还 = give back;举起 = lift up;站起来 = stand up."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"give in 的意思是:","options":["放大","参加","归还","屈服,让步"],"answer_index":3,"explanation_cn":"give in = 屈服、让步、认输。✓ He finally gave in,他最后让步了。\n顺带记:归还 = give back;参加 = take part in;放大 = enlarge."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"beside 的意思是:","options":["在…旁边","除…之外","在…下面","在…后面"],"answer_index":0,"explanation_cn":"beside = 在…旁边、紧挨着。✓ Sit beside me,坐我旁边。\n顺带记:除…之外 = besides;在…下面 = under;在…后面 = behind."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',6,NULL,'choice','{"stem":"besides 的意思是:","options":["尽管","在…旁边","除…之外(还)","反对"],"answer_index":2,"explanation_cn":"besides = 除…之外(还有)。✓ Besides English, he speaks French,除了英语他还说法语。\n顺带记:在…旁边 = beside;尽管 = in spite of;反对 = against."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',7,NULL,'cloze','{"stem":"第 1 空","context":"By the time I looked for my bag, someone ___1___ taken it. I was sure I ___2___ it on a chair by the door. The owner listened, then went out. He explained that his dog ___3___ carried the bag into the yard. The dog ___4___ done this many times before.","blank_no":1,"options":["had","has","have","was"],"answer_index":0,"explanation_cn":"\"有人拿走包\"在\"我去找\"之前,先发生用过去完成 had taken(这里填 had)。✓ By the time I looked, someone had taken it.\n✗ has:has 是现在完成,和过去的语境不符;✗ have:have 也是现在完成,人称也不对;✗ was:was taken 是被动,这里不需要."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',7,NULL,'cloze','{"stem":"第 2 空","context":"By the time I looked for my bag, someone ___1___ taken it. I was sure I ___2___ it on a chair by the door. The owner listened, then went out. He explained that his dog ___3___ carried the bag into the yard. The dog ___4___ done this many times before.","blank_no":2,"options":["had left","left","have left","was leaving"],"answer_index":0,"explanation_cn":"\"把包放椅子上\"比\"现在找不到\"更早,用过去完成 had left。✓ I was sure I had left it on a chair.\n✗ left:一般过去只说\"放过\",体现不出\"更早已完成\";✗ have left:have left 是现在完成,和过去语境不符;✗ was leaving:表\"正在放\",意思不对."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',7,NULL,'cloze','{"stem":"第 3 空","context":"By the time I looked for my bag, someone ___1___ taken it. I was sure I ___2___ it on a chair by the door. The owner listened, then went out. He explained that his dog ___3___ carried the bag into the yard. The dog ___4___ done this many times before.","blank_no":3,"options":["had","has","was","did"],"answer_index":0,"explanation_cn":"\"狗把包叼走\"在\"他解释\"之前就发生,用过去完成 had carried(这里填 had)。✓ His dog had carried the bag into the yard.\n✗ has:has 是现在完成,过去语境不用;✗ was:was carried 是被动,这里不需要;✗ did:did 不能和后面的 carried 一起构成过去完成."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',7,NULL,'cloze','{"stem":"第 4 空","context":"By the time I looked for my bag, someone ___1___ taken it. I was sure I ___2___ it on a chair by the door. The owner listened, then went out. He explained that his dog ___3___ carried the bag into the yard. The dog ___4___ done this many times before.","blank_no":4,"options":["had","has","have","did"],"answer_index":0,"explanation_cn":"\"以前干过很多次\"比故事发生的时刻更早,用过去完成 had done。✓ The dog had done this many times before.\n✗ has:has 是现在完成,和过去语境不符;✗ have:have done 人称和时态都不对;✗ did:did 是一般过去,配不上\"before 之前就\"的强调."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',8,NULL,'choice','{"stem":"Where did the writer have lunch?","options":["At a village café","On a train","At home","At a big hotel"],"answer_index":0,"explanation_cn":"课文开头说 I had had lunch at a village café,作者在一家乡村小餐馆吃的午饭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',8,NULL,'choice','{"stem":"Why couldn''t the writer pay the check?","options":["Because the owner was rude","Because the food was bad","Because the bag was gone","Because the café was closed"],"answer_index":2,"explanation_cn":"课文说 I can''t pay the check. I don''t have my bag,提包不见了所以付不了账。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',8,NULL,'choice','{"stem":"Who had taken the bag?","options":["Another customer","A thief","A waiter","The owner''s dog"],"answer_index":3,"explanation_cn":"课文结尾店主说 My dog had taken it into the yard,是店主的狗把包叼走了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',9,NULL,'choice','{"stem":"你想说\"我到那儿时,火车已经开走了\"(先发生的用过去完成):","options":["When I got there, the train had already left.","When I got there, the train has already left.","When I got there, the train leaves already.","When I got there, the train was leaving already ago."],"answer_index":0,"explanation_cn":"\"火车开走\"比\"我到\"更早,用 had already left 表示\"更早就已完成\"。✓ When I got there, the train had already left. 场合:解释自己没赶上车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',9,NULL,'choice','{"stem":"你想说\"请把书还给我\"(归还用 give back):","options":["Please giving the book back me.","Please give the book to back me.","Please give back to me the.","Please give the book back to me."],"answer_index":3,"explanation_cn":"\"把书还给我\"用 give back:give the book back to me。✓ Please give the book back to me. 场合:请别人归还借走的书。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',9,NULL,'choice','{"stem":"你想说\"除了英语,他还会说法语\"(除…之外用 besides):","options":["Among English, he can speak French.","Beside English, he can speak French.","Besides English, he can speak French.","Between English, he can speak French."],"answer_index":2,"explanation_cn":"\"除了英语还会法语\"用 besides(除…之外还)。✓ Besides English, he can speak French. 场合:介绍某人会好几门语言。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"check 在餐馆里的意思是:","options":["支票本以外的纸","账单","小费","菜单"],"answer_index":1,"explanation_cn":"在美语餐馆里 check 就是\"账单\"。✓ pay the check 付账。\n顺带记:菜单 = menu;小费 = tip;收据 = receipt."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"owner 的意思是:","options":["顾客","服务员","厨师","老板;主人"],"answer_index":3,"explanation_cn":"owner = 物主、老板、主人。✓ the owner of the café 餐馆老板。\n顺带记:顾客 = customer;服务员 = waiter;厨师 = cook / chef."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"\"When we arrived, the movie ___ already started.\"(我们到之前电影就已开始)","options":["had","did","was","has"],"answer_index":0,"stem_cn":"我们到的时候,电影已经开始了。","explanation_cn":"\"电影开始\"在\"我们到\"之前,先发生用过去完成 had started(这里填 had)。✓ When we arrived, the movie had already started."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"\"She told me she ___ lost her keys.\"(她说她之前已把钥匙丢了)","options":["was","had","have","has"],"answer_index":1,"stem_cn":"她告诉我她把钥匙弄丢了。","explanation_cn":"\"丢钥匙\"在\"她告诉我\"之前就发生,用过去完成 had lost。✓ She told me she had lost her keys."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"\"My dog often does this!\" 这句话的意思是:","options":["我的狗会做很多事!","我的狗从不这样!","我的狗经常干这种事!","我讨厌这只狗!"],"answer_index":2,"explanation_cn":"He often does this! 这里用 he 指那只狗,意思是\"我的狗经常干这种事\"。英语里常用 he / she 称呼自家宠物。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"朋友泄气时你说 \"Don''t give up!\",意思是:","options":["别放弃!","别还回来!","别送人!","别参加!"],"answer_index":0,"explanation_cn":"Don''t give up! 意思是\"别放弃、别泄气\"。give up = 放弃、不再坚持。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"What had the writer done with the bag before it went missing?","options":["Put it in the car","Given it to the owner","Left it on a chair beside the door","Taken it into the yard"],"answer_index":2,"passage":"After I had had lunch at a village café, I looked for my bag. I had left it on a chair beside the door, and now it wasn''t there! As I was looking for it, the owner came in. ''Did you enjoy your meal?'' he asked. ''Yes, thank you,'' I answered, ''but I can''t pay the check. I don''t have my bag.'' The owner smiled and immediately went out. In a few minutes, he came back with my bag and gave it back to me. ''I''m very sorry,'' he said. ''My dog had taken it into the yard. He often does this!''","explanation_cn":"课文说 I had left it on a chair beside the door,作者先前把包放在门边椅子上。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"Why did the owner smile and go out at once?","options":["Because he was angry with the writer","Because he knew his dog had taken the bag","Because the café was closing","Because he wanted more money"],"answer_index":1,"passage":"After I had had lunch at a village café, I looked for my bag. I had left it on a chair beside the door, and now it wasn''t there! As I was looking for it, the owner came in. ''Did you enjoy your meal?'' he asked. ''Yes, thank you,'' I answered, ''but I can''t pay the check. I don''t have my bag.'' The owner smiled and immediately went out. In a few minutes, he came back with my bag and gave it back to me. ''I''m very sorry,'' he said. ''My dog had taken it into the yard. He often does this!''","explanation_cn":"店主一听就笑着出去,是因为他知道自家狗又把包叼走了。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"What did the owner say at the end?","options":["''You must pay the check now.''","''I never saw your bag.''","''My dog had taken it into the yard. He often does this!''","''Please leave my café.''"],"answer_index":2,"audio":"After I had had lunch at a village café, I looked for my bag. I had left it on a chair beside the door, and now it wasn''t there! As I was looking for it, the owner came in. ''Did you enjoy your meal?'' he asked. ''Yes, thank you,'' I answered, ''but I can''t pay the check. I don''t have my bag.'' The owner smiled and immediately went out. In a few minutes, he came back with my bag and gave it back to me. ''I''m very sorry,'' he said. ''My dog had taken it into the yard. He often does this!''","explanation_cn":"课文结尾店主说:\"我的狗把它叼到院子里了,他经常干这种事!\""}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l18',10,NULL,'choice','{"stem":"Did the writer get the bag back?","options":["Yes, the owner brought it back","Yes, but it was empty","No, it was lost forever","No, the dog ate it"],"answer_index":0,"audio":"After I had had lunch at a village café, I looked for my bag. I had left it on a chair beside the door, and now it wasn''t there! As I was looking for it, the owner came in. ''Did you enjoy your meal?'' he asked. ''Yes, thank you,'' I answered, ''but I can''t pay the check. I don''t have my bag.'' The owner smiled and immediately went out. In a few minutes, he came back with my bag and gave it back to me. ''I''m very sorry,'' he said. ''My dog had taken it into the yard. He often does this!''","explanation_cn":"课文说 he came back with my bag and gave it back to me,店主把包拿回来还给了作者。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l19',2,3,19,'Sold out','票已售完','can / could / may / might 的用法(主考:表请求 Can/Could/May I…?——could/might 更委婉 · 表推测''可能''He may come · may/might + have + 过去分词表''可能已经''——对过去的推测)+ 感叹句 What a…! 与 might as well(辅考:What a pity! · might as well = 不妨、还是…的好)','剧就要开演了,匆匆赶到售票处却被告知票已售完;正巧一名男子来退票,但那两张是下周三的——''我还是买下吧'',我丧气地说','{"q":"Listen and answer — When will the writer see the play?","options":["At next Wednesday''s performance","That same evening","Never, the play was canceled","The following morning"],"answer_index":0}'::jsonb,'{"title":"说''可以…吗 / 可能…''(can / could / may / might)","intro":"本课讲用 can / could / may / might 提出请求(''可以…吗'')和表示推测(''可能…'')。请求时 could / might 更委婉;''可能已经…了''用 may/might + have + 过去分词。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["提请求''可以…吗'':Can / Could / May / Might I …?","May I have two tickets, please?"],["could / might 比 can / may 更委婉、更客气","Could I have those two tickets, please?"],["may / might 表推测''可能、也许''","The play may begin at any moment."],["''可能已经…了''= may/might + have + 过去分词","It may have begun already."]]},"specialRules":[{"rule":"感叹句 What a + 名词:What a pity! 真遗憾!","mark":"What a…!"},{"rule":"might as well = 不妨、还是…的好:I might as well take them.","mark":"might as well"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',1,NULL,'''The play may begin at any moment,'' I said.','"剧马上就要开演了,"我说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',2,NULL,'''It may have begun already,'' Susan answered.','"也许已经开演了呢,"苏珊回答说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',3,NULL,'I hurried to the box office. ''May I have two tickets, please?'' I asked.','我匆匆赶到售票处,问:"我可以买两张票吗?"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',4,NULL,'''I''m sorry, we''ve sold out,'' the girl said.','"对不起,票已售完,"那姑娘说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',5,NULL,'''What a pity!'' Susan exclaimed.','"真可惜!"苏珊大声说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',6,NULL,'Just then, a man hurried to the box office.','正在这时,一个男子匆匆奔向售票处。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',7,NULL,'''Can I return these two tickets?'' he asked. ''Certainly,'' the girl said.','"我可以退掉这两张票吗?"他问。"当然可以,"那姑娘说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',8,NULL,'I went back to the box office at once.','我马上又回到售票处。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',9,NULL,'''Could I have those two tickets, please?'' I asked.','"我可以买那两张票吗?"我问。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l19',10,NULL,'''Certainly,'' the girl said, ''but they''re for next Wednesday''s performance. Do you still want them?'' ''I might as well have them,'' I said sadly.','"当然可以,不过这两张票是下星期三的,您还要吗?""我还是买下的好,"我垂头丧气地说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
