INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp1','choice','{"stem":"表示''请求''(可以…吗)可以用哪些词?","options":["must / should","will / shall","can / could / may / might","do / does"],"answer_index":2,"explanation_cn":"提出请求\"可以…吗\",可以用 can / could / may / might。✓ Can I / May I have a ticket?"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp1','choice','{"stem":"\"___ I have two tickets, please?\"(请求:我可以买两张票吗)","options":["Do","Am","Shall","May"],"answer_index":3,"stem_cn":"我可以买两张票吗?","explanation_cn":"\"我可以买两张票吗\"是请求,用 May I have…。✓ May I have two tickets, please? Do / Am / Shall 都不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp1','choice','{"stem":"\"___ I borrow your pen?\"(请求:可以借用你的笔吗)","options":["Is","Can","Does","Being"],"answer_index":1,"stem_cn":"我可以借你的笔用一下吗?","explanation_cn":"\"可以借你的笔吗\"是请求,用 Can I borrow…。✓ Can I borrow your pen? Does / Is / Being 都不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp2','choice','{"stem":"提请求时,哪组词语气更委婉、更客气?","options":["Will / Shall","Can / May 就是最客气的","Do / Does","Could / Might"],"answer_index":3,"explanation_cn":"提请求时 could / might 比 can / may 更委婉、更客气。✓ Could I have those tickets, please?"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp2','choice','{"stem":"\"___ I have those two tickets, please?\"(更委婉地请求)","options":["Could","Do","Am","Was"],"answer_index":0,"stem_cn":"我可以要那两张票吗?","explanation_cn":"更委婉地请求,用 Could I have…。✓ Could I have those two tickets, please? Do / Was / Am 都不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp3','choice','{"stem":"may / might 表推测,意思是:","options":["必须","从不","当然","可能,也许"],"answer_index":3,"explanation_cn":"may / might 表推测,意思是\"可能、也许\",说话人没有十足把握。✓ He may come tomorrow."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp3','choice','{"stem":"\"The play ___ begin at any moment.\"(推测:可能随时开演)","options":["must","is","may","does"],"answer_index":2,"stem_cn":"这出戏可能随时开演。","explanation_cn":"\"可能随时开演\"是推测,用 may begin。✓ The play may begin at any moment. must 是\"一定\"、does / is 不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp3','choice','{"stem":"\"He ___ come tomorrow; I''m not sure.\"(推测:可能来)","options":["may","will","does","is"],"answer_index":0,"stem_cn":"他明天可能会来,我不确定。","explanation_cn":"\"可能来,我不确定\"是推测,用 may come。✓ He may come tomorrow; I''m not sure. will 是\"一定会\",把握太足。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp4','choice','{"stem":"''可能已经…了''(对过去的推测)用什么结构?","options":["will + 动词原形","must + 动词原形","is / are + 动词-ing","may / might + have + 过去分词"],"answer_index":3,"explanation_cn":"\"可能已经…了\"(对过去的推测)= may / might + have + 过去分词。✓ It may have begun already."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp4','choice','{"stem":"\"It ___ have begun already.\"(推测:可能已经开演了)","options":["may","does","is","will"],"answer_index":0,"stem_cn":"戏可能已经开演了。","explanation_cn":"\"可能已经开演了\"是对过去的推测,用 may have begun(这里填 may)。✓ It may have begun already."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp4','choice','{"stem":"\"He ___ have telephoned last night, but I''m not sure.\"(推测:可能已打过电话)","options":["does","will","may","must"],"answer_index":2,"stem_cn":"他昨晚可能打过电话,我不确定。","explanation_cn":"\"昨晚可能已打过电话\"是对过去的推测,用 may have telephoned(这里填 may)。✓ He may have telephoned last night."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp5','choice','{"stem":"\"Can I return these tickets?\" 这里 can 表示的是:","options":["请求(可以…吗)","命令","过去的能力","推测(可能)"],"answer_index":0,"explanation_cn":"Can I return these tickets? 是在问\"我可以退这些票吗\",这里 can 表请求。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp5','choice','{"stem":"\"He may be at home now.\" 这里 may 表示的是:","options":["请求(可以…吗)","邀请","义务(必须)","推测(可能)"],"answer_index":3,"explanation_cn":"He may be at home now. 是在猜\"他现在可能在家\",这里 may 表推测。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp6','choice','{"stem":"\"___ I ask you a question, please?\"(委婉请求)","options":["Shall","Do","May","Am"],"answer_index":2,"stem_cn":"我可以问你一个问题吗?","explanation_cn":"委婉地请求,用 May I ask…。✓ May I ask you a question, please?"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp6','choice','{"stem":"\"She ___ have missed the bus.\"(推测:可能已经错过了)","options":["will","is","does","may"],"answer_index":3,"stem_cn":"她可能已经错过公交车了。","explanation_cn":"\"可能已经错过公交\"是对过去的推测,用 may have missed(这里填 may)。✓ She may have missed the bus."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp7','choice','{"stem":"\"___ a pity!\"(意思是''真遗憾!'')","options":["That","Which","What","How"],"answer_index":2,"stem_cn":"真遗憾!","explanation_cn":"感叹\"真遗憾\"用 What a + 名词:What a pity! How 后面接形容词/副词,这里接名词 pity,所以用 What。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp8','choice','{"stem":"might as well 的意思是:","options":["一定要","最好别","绝不","还是…的好;不妨"],"answer_index":3,"explanation_cn":"might as well = 不妨、还是…的好,表示\"虽然没那么想,但还是做了吧\"。✓ I might as well have them."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',5,'am2_l19_gp8','choice','{"stem":"\"I ___ as well take the Wednesday tickets.\"(不妨、还是…好)","options":["must","might","should","will"],"answer_index":1,"stem_cn":"我还是买下星期三的票吧。","explanation_cn":"\"还是买下吧\"用 might as well。✓ I might as well take the Wednesday tickets. must / will / should 语气不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"美语里剧院/影院\"售票处\"常说:","options":["box office","sell room","pay desk","ticket office"],"answer_index":0,"explanation_cn":"美语里剧院、影院的\"售票处\"常说 box office;英式常说 ticket office。✓ hurry to the box office."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"美语\"电影院\"常说:","options":["film house","movie theater","picture hall","cinema"],"answer_index":1,"explanation_cn":"美语\"电影院\"常说 movie theater 或 the movies;英式说 cinema。✓ go to the movie theater."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"What a pity! 的意思是:","options":["多谢!","别客气!","真遗憾!","太好了!"],"answer_index":2,"explanation_cn":"What a pity! = 真遗憾!真可惜!表示惋惜。\n顺带记:太好了 = Great!;多谢 = Thank you!;别客气 = You''re welcome."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"sold out 的意思是:","options":["票(货)售完了","退货","刚开始卖","打折出售"],"answer_index":0,"explanation_cn":"sold out = (票、货)卖完了、售罄。✓ We''ve sold out,票已售完。\n顺带记:打折出售 = on sale;开始发售 = go on sale;退货 = return the goods."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"at once 的意思是:","options":["慢慢地","偶尔","立刻,马上","一次也没"],"answer_index":2,"explanation_cn":"at once = 立刻、马上。✓ I went back at once,我马上回去了。\n顺带记:偶尔 = sometimes;一次也没 = never once;慢慢地 = slowly."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',6,NULL,'choice','{"stem":"might as well 的意思是:","options":["还是…的好;不妨","根本不该","差一点","务必要"],"answer_index":0,"explanation_cn":"might as well = 不妨、还是…的好。✓ We might as well go home,我们还是回家吧。\n顺带记:根本不该 = should never;务必要 = be sure to;差一点 = nearly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',7,NULL,'cloze','{"stem":"第 1 空","context":"Susan was not sure. ''The play ___1___ have begun already,'' she said. At the box office I asked politely, ''___2___ I have two tickets?'' They were sold out. Then a man returned his, so the girl said I ___3___ have them — but for next Wednesday. ''I ___4___ as well take them,'' I said sadly.","blank_no":1,"options":["may","will","must","is"],"answer_index":0,"explanation_cn":"\"可能已经开演了\"是对过去的推测,用 may have begun(这里填 may)。✓ The play may have begun already.\n✗ will:will 是\"一定会\",把握太足,不是推测;✗ must:must have begun 是\"一定已开始\",语气太肯定;✗ is:is have begun 根本不通."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',7,NULL,'cloze','{"stem":"第 2 空","context":"Susan was not sure. ''The play ___1___ have begun already,'' she said. At the box office I asked politely, ''___2___ I have two tickets?'' They were sold out. Then a man returned his, so the girl said I ___3___ have them — but for next Wednesday. ''I ___4___ as well take them,'' I said sadly.","blank_no":2,"options":["May","Do","Shall","Am"],"answer_index":0,"explanation_cn":"\"我可以买两张票吗\"是请求,用 May I have…。✓ May I have two tickets?\n✗ Do:Do I have 是\"我有…吗\",意思不对;✗ Shall:Shall I 是\"要不要我…\",是提议不是请求;✗ Am:Am I have 不通."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',7,NULL,'cloze','{"stem":"第 3 空","context":"Susan was not sure. ''The play ___1___ have begun already,'' she said. At the box office I asked politely, ''___2___ I have two tickets?'' They were sold out. Then a man returned his, so the girl said I ___3___ have them — but for next Wednesday. ''I ___4___ as well take them,'' I said sadly.","blank_no":3,"options":["could","must","should","would"],"answer_index":0,"explanation_cn":"\"姑娘说我可以买那两张票\",表示\"可以、能够\",用 could。✓ She said I could have them.\n✗ must:must 是\"必须\",语气不对;✗ should:should 是\"应该\",不是\"可以\";✗ would:would have them 意思不对."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',7,NULL,'cloze','{"stem":"第 4 空","context":"Susan was not sure. ''The play ___1___ have begun already,'' she said. At the box office I asked politely, ''___2___ I have two tickets?'' They were sold out. Then a man returned his, so the girl said I ___3___ have them — but for next Wednesday. ''I ___4___ as well take them,'' I said sadly.","blank_no":4,"options":["might","must","will","does"],"answer_index":0,"explanation_cn":"\"我还是买下吧\"用 might as well(不妨、还是…好)。✓ I might as well take them.\n✗ must:must as well 没有这种说法;✗ will:will as well 不通;✗ does:does as well 不通."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',8,NULL,'choice','{"stem":"Where did the writer go to buy tickets?","options":["To a restaurant","To the train station","To the box office","To the library"],"answer_index":2,"explanation_cn":"课文说 I hurried to the box office,作者赶到售票处买票。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',8,NULL,'choice','{"stem":"Why couldn''t the writer buy tickets at first?","options":["The office was closed","He had no money","He was too late for the bus","They were sold out"],"answer_index":3,"explanation_cn":"课文说 we''ve sold out,票已经卖光了,所以一开始买不到。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',8,NULL,'choice','{"stem":"The two tickets the writer finally got were for:","options":["Next Wednesday''s performance","That same evening","A movie","A concert"],"answer_index":0,"explanation_cn":"课文说 they''re for next Wednesday''s performance,最后买到的票是下星期三的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',9,NULL,'choice','{"stem":"你想委婉地问\"我能借用你的电话吗\"(委婉请求用 Could):","options":["I could use your phone?","Could I use your phone?","Do I could use your phone?","Could I using your phone?"],"answer_index":1,"explanation_cn":"委婉地问\"能借用电话吗\",用 Could I use…。✓ Could I use your phone? 场合:客气地向别人借东西。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',9,NULL,'choice','{"stem":"你想说\"他可能已经到家了\"(推测''可能已经''用 may have + 过去分词):","options":["He may has gone home already.","He may going home already.","He may gone home already.","He may have gone home already."],"answer_index":3,"explanation_cn":"\"可能已经到家了\"是对过去的推测,用 may have gone。✓ He may have gone home already. 场合:不太确定对方是否已回家。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',9,NULL,'choice','{"stem":"你想感叹\"真遗憾!\"(感叹用 What a + 名词):","options":["What a pity!","What pity a!","How a pity!","What an pity!"],"answer_index":0,"explanation_cn":"感叹\"真遗憾\"用 What a + 名词:What a pity! ✓ 场合:听到不巧的消息时惋惜地说。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"exclaim 的意思是:","options":["沉默","低声说","回答","惊叫,大声说"],"answer_index":3,"explanation_cn":"exclaim = 惊叫、大声说(带着情绪)。✓ ''What a pity!'' Susan exclaimed.\n顺带记:低声说 = whisper;喊叫 = shout;回答 = answer."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"pity 的意思是:","options":["礼物","令人遗憾的事","机会","怜悯的对象以外的喜事"],"answer_index":1,"explanation_cn":"pity = 令人遗憾、可惜的事。✓ What a pity! 真遗憾!\n顺带记:运气 = luck;机会 = chance;麻烦 = trouble."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"\"___ I ask you a question, please?\"(委婉请求)","options":["Shall","Am","Do","May"],"answer_index":3,"stem_cn":"我可以问你一个问题吗?","explanation_cn":"委婉地请求\"我可以问个问题吗\",用 May I ask…。✓ May I ask you a question, please?"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"\"He ___ have missed the train.\"(推测:可能已经)","options":["may","is","does","will"],"answer_index":0,"stem_cn":"他可能已经错过火车了。","explanation_cn":"\"可能已经错过火车了\"是对过去的推测,用 may have missed(这里填 may)。✓ He may have missed the train."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"\"What a pity!\" 这句话的意思是:","options":["太棒了!","快点!","真遗憾!","无所谓!"],"answer_index":2,"explanation_cn":"What a pity! 意思是\"真遗憾、真可惜\",表示惋惜。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"\"I might as well go.\" 这句话的意思是:","options":["我还是去了吧(不妨去)","我必须去","我绝不去","我不想去"],"answer_index":0,"explanation_cn":"I might as well go. 意思是\"我还是去了吧、不妨去\",虽然不是很想,但还是做了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"Why couldn''t the writer see the play at first?","options":["The theater was closed","The tickets were sold out","It was raining hard","Susan didn''t want to go"],"answer_index":1,"passage":"''The play may begin at any moment,'' I said. ''It may have begun already,'' Susan answered. I hurried to the box office. ''May I have two tickets, please?'' I asked. ''I''m sorry, we''ve sold out,'' the girl said. ''What a pity!'' Susan exclaimed. Just then, a man hurried to the box office. ''Can I return these two tickets?'' he asked. ''Certainly,'' the girl said. I went back to the box office at once. ''Could I have those two tickets, please?'' I asked. ''Certainly,'' the girl said, ''but they''re for next Wednesday''s performance. Do you still want them?'' ''I might as well have them,'' I said sadly.","explanation_cn":"课文说 we''ve sold out,票已售完,所以一开始看不了戏。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"What were the two tickets the writer finally bought for?","options":["Next Wednesday''s performance","A morning show","That very evening","A different play"],"answer_index":0,"passage":"''The play may begin at any moment,'' I said. ''It may have begun already,'' Susan answered. I hurried to the box office. ''May I have two tickets, please?'' I asked. ''I''m sorry, we''ve sold out,'' the girl said. ''What a pity!'' Susan exclaimed. Just then, a man hurried to the box office. ''Can I return these two tickets?'' he asked. ''Certainly,'' the girl said. I went back to the box office at once. ''Could I have those two tickets, please?'' I asked. ''Certainly,'' the girl said, ''but they''re for next Wednesday''s performance. Do you still want them?'' ''I might as well have them,'' I said sadly.","explanation_cn":"课文说 they''re for next Wednesday''s performance,最后买的票是下星期三的。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"What did Susan exclaim when the tickets were sold out?","options":["''Buy them anyway!''","''How wonderful!''","''Let''s go home.''","''What a pity!''"],"answer_index":3,"audio":"''The play may begin at any moment,'' I said. ''It may have begun already,'' Susan answered. I hurried to the box office. ''May I have two tickets, please?'' I asked. ''I''m sorry, we''ve sold out,'' the girl said. ''What a pity!'' Susan exclaimed. Just then, a man hurried to the box office. ''Can I return these two tickets?'' he asked. ''Certainly,'' the girl said. I went back to the box office at once. ''Could I have those two tickets, please?'' I asked. ''Certainly,'' the girl said, ''but they''re for next Wednesday''s performance. Do you still want them?'' ''I might as well have them,'' I said sadly.","explanation_cn":"票售完时苏珊惊呼 ''What a pity!''(真遗憾!)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l19',10,NULL,'choice','{"stem":"How did the writer feel at the end?","options":["Sad and disappointed","Excited","Very happy","Angry and loud"],"answer_index":0,"audio":"''The play may begin at any moment,'' I said. ''It may have begun already,'' Susan answered. I hurried to the box office. ''May I have two tickets, please?'' I asked. ''I''m sorry, we''ve sold out,'' the girl said. ''What a pity!'' Susan exclaimed. Just then, a man hurried to the box office. ''Can I return these two tickets?'' he asked. ''Certainly,'' the girl said. I went back to the box office at once. ''Could I have those two tickets, please?'' I asked. ''Certainly,'' the girl said, ''but they''re for next Wednesday''s performance. Do you still want them?'' ''I might as well have them,'' I said sadly.","explanation_cn":"课文结尾 I said sadly,作者垂头丧气,又失望又无奈。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l20',2,3,20,'One man in a boat','独坐孤舟','动名词(主考:动词 + -ing 当名词用——作主语 Fishing is fun · 作介词宾语 interested in fishing · 完成式 having done 表更早发生 · 介词/连词 + 动名词连接短句 without/before/after doing)+ 常见搭配(辅考:enjoy/give up/finish + 动名词 · instead of / be afraid of + 动名词)','钓鱼是我最爱的运动,却常常一无所获、空袋回家;朋友劝我''别钓了,浪费时间''——他们不懂,我要的只是独坐孤舟、什么也不干','{"q":"Listen and answer — Why is fishing the writer''s favorite sport?","options":["Because he loves sitting in a boat and doing nothing","Because he catches many fish","Because he wins fishing contests","Because his friends fish too"],"answer_index":0}'::jsonb,'{"title":"把动词当名词用(动名词 -ing)","intro":"本课讲动名词——动词加 -ing 后当名词用。它可以放句首当名词、跟在介词后面、还能把两个短句连起来。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["动名词 = 动词 + -ing,当名词用","Fishing is my favorite sport."],["放在句首当名词(后面 be 用单数 is)","Sitting in a boat is my real pleasure."],["介词(in / on / of / without)后面用动名词","I''m interested in fishing."],["完成式 having done:比句子的动作更早发生","After having spent the morning, I went home."]]},"specialRules":[{"rule":"enjoy / give up / finish 后面只能接动名词:enjoy reading, give up fishing","mark":"只接 -ing"},{"rule":"instead of / be afraid of + 动名词:instead of catching fish","mark":"介词 + -ing"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',1,NULL,'Fishing is my favorite sport.','钓鱼是我最喜爱的一项运动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',2,NULL,'I often fish for hours without catching anything.','我经常一钓数小时却一无所获。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',3,NULL,'But this does not worry me. Some fishermen are unlucky.','但我从不为此烦恼。有些垂钓者就是不走运。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',4,NULL,'Instead of catching fish, they catch old boots and trash.','他们往往鱼钓不到,却钓上来些旧靴子和垃圾。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',5,NULL,'I am even less lucky. I never catch anything — not even old boots.','我的运气甚至还不及他们。我什么东西都未钓到过——就连旧靴子也没有。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',6,NULL,'After having spent whole mornings on the river, I always go home with an empty bag.','我总是在河上呆整整一上午,然后空着袋子回家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',7,NULL,'''You must give up fishing!'' my friends say. ''It''s a waste of time.''','"你可别再钓鱼了!"我的朋友们说,"这是浪费时间。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',8,NULL,'But they don''t realize one important thing.','然而他们没有认识到重要的一点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',9,NULL,'I''m not really interested in fishing.','我并不是真的对钓鱼有兴趣。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l20',10,NULL,'I am only interested in sitting in a boat and doing nothing at all!','我感兴趣的只是独坐孤舟,无所事事!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
