INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp1','choice','{"stem":"动名词是怎么构成、当什么用的?","options":["动词 + -ing,当名词用","动词 + -ed,当形容词用","be + 动词,表进行","动词原形,当命令用"],"answer_index":0,"explanation_cn":"动名词 = 动词 + -ing,把动作当名词来用。✓ Fishing(钓鱼)、Swimming(游泳)都是动名词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp1','choice','{"stem":"下面哪个是动名词(-ing 当名词用)?","options":["Swim right now!","Swimming is fun.","He swims fast.","He is swimming now."],"answer_index":1,"explanation_cn":"Swimming is fun 里的 Swimming 是动名词(当名词用);he swims / is swimming / Swim! 里的都不是动名词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp2','choice','{"stem":"动名词作主语时,后面的谓语动词一般用:","options":["过去分词","不定式 to do","单数(is / was)","复数(are / were)"],"answer_index":2,"explanation_cn":"动名词作主语时看作单数,后面的谓语动词用 is / was。✓ Swimming is good for you."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp2','choice','{"stem":"\"___ is my favorite sport.\"(动名词作主语:钓鱼)","options":["Fishes","Fish","Fished","Fishing"],"answer_index":3,"stem_cn":"钓鱼是我最喜欢的运动。","explanation_cn":"\"钓鱼\"作主语,用动名词 Fishing。✓ Fishing is my favorite sport. Fish / Fished / Fishes 都不能表示\"钓鱼这件事\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp2','choice','{"stem":"\"___ television is fun.\"(动名词作主语:看电视)","options":["Watching","Watches","Watch","Watched"],"answer_index":0,"stem_cn":"看电视很有意思。","explanation_cn":"\"看电视\"作主语,用动名词 Watching。✓ Watching television is fun."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp3','choice','{"stem":"介词(in / on / of / without…)后面的动词要用:","options":["过去式","动词原形","动名词(-ing)","不定式 to do"],"answer_index":2,"explanation_cn":"介词(in / on / of / without…)后面接动词时,一律用动名词。✓ interested in fishing, keen on cycling."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp3','choice','{"stem":"\"I''m interested in ___.\"(be interested in + 动名词:钓鱼)","options":["fished","fishing","fish","to fish"],"answer_index":1,"stem_cn":"我对钓鱼感兴趣。","explanation_cn":"be interested in 后面接动名词,\"对钓鱼感兴趣\"= interested in fishing。✓ I''m interested in fishing."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp3','choice','{"stem":"\"He is keen on ___ every day.\"(介词 on + 动名词:骑车)","options":["to cycle","cycled","cycle","cycling"],"answer_index":3,"stem_cn":"他每天都热衷于骑车。","explanation_cn":"介词 on 后面用动名词,keen on cycling = 热衷骑车。✓ He is keen on cycling."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp4','choice','{"stem":"动名词完成式 having done 表示的是:","options":["这个动作比句子的动作更早发生","被动的动作","正在进行的动作","将来才发生的动作"],"answer_index":0,"explanation_cn":"动名词完成式 having done,强调它比句子里的动作更早发生。✓ After having spent the morning, I went home."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp4','choice','{"stem":"\"After ___ the letter, he went out.\"(动名词完成式:写完之后)","options":["wrote","to write","having written","write"],"answer_index":2,"stem_cn":"写完信后,他就出去了。","explanation_cn":"\"写完信\"在\"出去\"之前,用动名词完成式 having written。✓ After having written the letter, he went out."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp5','choice','{"stem":"\"He left without ___ goodbye.\"(介词 without 后用动名词:说再见)","options":["to say","saying","said","say"],"answer_index":1,"stem_cn":"他没说再见就走了。","explanation_cn":"without 是介词,后面用动名词 saying,\"没说再见\"= without saying goodbye。✓ He left without saying goodbye."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp5','choice','{"stem":"\"Before ___ the room, he turned off the light.\"(before 后用动名词:离开)","options":["left","to leave","leave","leaving"],"answer_index":3,"stem_cn":"离开房间前,他关了灯。","explanation_cn":"before 后面接动名词 leaving,\"离开房间前\"= before leaving the room。✓ Before leaving the room, he turned off the light."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp6','choice','{"stem":"\"I enjoy ___ in bed.\"(enjoy 后接动名词:看书)","options":["to read","reads","reading","read"],"answer_index":2,"stem_cn":"我喜欢躺在床上看书。","explanation_cn":"enjoy 后面只能接动名词,enjoy reading = 喜欢看书。✓ I enjoy reading in bed."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp6','choice','{"stem":"\"Thank you for ___ me.\"(for 后接动名词:帮我)","options":["help","to help","helped","helping"],"answer_index":3,"stem_cn":"谢谢你帮我。","explanation_cn":"for 是介词,后面用动名词 helping,\"谢谢你帮我\"= Thank you for helping me。✓"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp7','choice','{"stem":"下面哪个动词后面只能接动名词(不能接 to do)?","options":["decide(decide to do)","enjoy(enjoy doing)","hope(hope to do)","want(want to do)"],"answer_index":1,"explanation_cn":"enjoy 后面只能接动名词 enjoy doing;want / hope / decide 后面接 to do,不接动名词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp7','choice','{"stem":"\"I finished ___ my homework.\"(finish 后接动名词:做完作业)","options":["doing","did","do","to do"],"answer_index":0,"stem_cn":"我做完了作业。","explanation_cn":"finish 后面只能接动名词,finish doing = 做完。✓ I finished doing my homework."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp8','choice','{"stem":"instead of 后面接动词时,要用:","options":["不定式 to do","过去式","动名词(instead of doing)","动词原形"],"answer_index":2,"explanation_cn":"instead of 是介词短语,后面接动名词。✓ instead of catching fish 而不是钓鱼。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',5,'am2_l20_gp8','choice','{"stem":"\"She is afraid of ___ alone.\"(be afraid of + 动名词:独自待着)","options":["to stay","stay","stayed","staying"],"answer_index":3,"stem_cn":"她害怕独自待着。","explanation_cn":"be afraid of 后面接动名词,\"害怕独自待着\"= afraid of staying alone。✓ She is afraid of staying alone."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"美语\"最喜欢的\"拼作:","options":["favrite","favourite","favorite","favorito"],"answer_index":2,"explanation_cn":"美语\"最喜欢的\"拼 favorite;英式拼 favourite。✓ my favorite sport."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"美语\"垃圾\"常说:","options":["dust","waste bin","rubbish","trash / garbage"],"answer_index":3,"explanation_cn":"美语\"垃圾\"常说 trash 或 garbage;英式说 rubbish。✓ old boots and trash."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"give up 的意思是:","options":["举起","赠送","放弃;戒掉","追上"],"answer_index":2,"explanation_cn":"give up = 放弃;也指戒掉(烟酒等)。✓ give up fishing 别再钓鱼。\n顺带记:举起 = lift up;赠送 = give away;追上 = catch up."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"a waste of time 的意思是:","options":["省时间","很值得","很花钱","浪费时间"],"answer_index":3,"explanation_cn":"a waste of time = 浪费时间。✓ It''s a waste of time,这是浪费时间。\n顺带记:很花钱 = cost a lot;很值得 = worth it;省时间 = save time."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"be interested in 的意思是:","options":["对…感兴趣","对…厌烦","参与其中","负责…"],"answer_index":0,"explanation_cn":"be interested in = 对…感兴趣。✓ interested in fishing 对钓鱼感兴趣。\n顺带记:对…厌烦 = be tired of;负责… = be in charge of;擅长… = be good at."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',6,NULL,'choice','{"stem":"instead of 的意思是:","options":["由于","除…之外","而不是;代替","为了"],"answer_index":2,"explanation_cn":"instead of = 而不是、代替。✓ instead of catching fish 没钓到鱼(而是别的)。\n顺带记:除…之外 = besides;为了 = for;由于 = because of."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',7,NULL,'cloze','{"stem":"第 1 空","context":"Fishing is my favorite sport. I often fish for hours without ___1___ anything. Instead of ___2___ home, I stay on the river all morning. ___3___ in a boat is my real pleasure. My friends say I should give up ___4___, but I don''t agree.","blank_no":1,"options":["catching","catch","caught","to catch"],"answer_index":0,"explanation_cn":"without 是介词,后面用动名词 catching。✓ without catching anything 什么也没钓到。\n✗ catch:介词后不能用动词原形;✗ caught:介词后不用过去式;✗ to catch:介词后不接不定式."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',7,NULL,'cloze','{"stem":"第 2 空","context":"Fishing is my favorite sport. I often fish for hours without ___1___ anything. Instead of ___2___ home, I stay on the river all morning. ___3___ in a boat is my real pleasure. My friends say I should give up ___4___, but I don''t agree.","blank_no":2,"options":["going","go","went","to go"],"answer_index":0,"explanation_cn":"instead of 后面用动名词 going。✓ instead of going home 而不是回家。\n✗ go:介词后不能用原形;✗ went:介词后不用过去式;✗ to go:介词后不接不定式."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',7,NULL,'cloze','{"stem":"第 3 空","context":"Fishing is my favorite sport. I often fish for hours without ___1___ anything. Instead of ___2___ home, I stay on the river all morning. ___3___ in a boat is my real pleasure. My friends say I should give up ___4___, but I don''t agree.","blank_no":3,"options":["Sitting","Sit","Sat","Sits"],"answer_index":0,"explanation_cn":"\"坐在船里\"作主语,用动名词 Sitting。✓ Sitting in a boat is my pleasure.\n✗ Sit:原形不能作主语;✗ Sat:过去式不能作主语;✗ Sits:第三人称形式不能作主语."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',7,NULL,'cloze','{"stem":"第 4 空","context":"Fishing is my favorite sport. I often fish for hours without ___1___ anything. Instead of ___2___ home, I stay on the river all morning. ___3___ in a boat is my real pleasure. My friends say I should give up ___4___, but I don''t agree.","blank_no":4,"options":["fishing","fish","to fish","fished"],"answer_index":0,"explanation_cn":"give up 后面只能接动名词 fishing。✓ give up fishing 放弃钓鱼。\n✗ fish:give up 后不接原形;✗ to fish:give up 后不接不定式;✗ fished:give up 后不接过去式."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',8,NULL,'choice','{"stem":"What is the writer''s favorite sport?","options":["Fishing","Swimming","Cycling","Reading"],"answer_index":0,"explanation_cn":"课文第一句 Fishing is my favorite sport,作者最爱的运动是钓鱼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',8,NULL,'choice','{"stem":"Does the writer often catch fish?","options":["Yes, he catches a lot","Yes, but only boots","No, he never catches anything","No, but he catches a lot of trash"],"answer_index":2,"explanation_cn":"课文说 I never catch anything,作者从来什么都钓不到。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',8,NULL,'choice','{"stem":"What is the writer really interested in?","options":["Catching big fish","Sitting in a boat and doing nothing","Selling fish at the market","Winning fishing contests"],"answer_index":1,"explanation_cn":"课文结尾说 I am only interested in sitting in a boat and doing nothing,他真正感兴趣的是独坐孤舟、无所事事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',9,NULL,'choice','{"stem":"你想说\"钓鱼是我最喜欢的运动\"(动名词放句首当名词):","options":["Fishing is my favorite sport.","Fish is my favorite sport.","To fishing is my favorite sport.","Fished is my favorite sport."],"answer_index":0,"explanation_cn":"\"钓鱼\"放句首当名词,用动名词 Fishing。✓ Fishing is my favorite sport. 场合:介绍自己最爱的运动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',9,NULL,'choice','{"stem":"你想说\"他不打招呼就走了\"(without + 动名词):","options":["He left no saying goodbye.","He left without to say goodbye.","He left without say goodbye.","He left without saying goodbye."],"answer_index":3,"explanation_cn":"without 后面用动名词 saying,\"没说再见就走\"= left without saying goodbye。✓ 场合:描述某人悄悄离开。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',9,NULL,'choice','{"stem":"你想说\"我对唱歌感兴趣\"(be interested in + 动名词):","options":["I am interested to sing.","I am interested in singing.","I am interested in to sing.","I am interested in sing."],"answer_index":1,"explanation_cn":"be interested in 后面接动名词 singing,\"对唱歌感兴趣\"。✓ I am interested in singing. 场合:说自己喜欢什么。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"realize 的意思是:","options":["忘记","拒绝","怀疑","意识到,认识到"],"answer_index":3,"explanation_cn":"realize = 意识到、认识到。✓ they don''t realize 他们没意识到。\n顺带记:忘记 = forget;怀疑 = doubt;拒绝 = refuse."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"waste 的意思是:","options":["节省","浪费","赚取","收集"],"answer_index":1,"explanation_cn":"waste = 浪费。✓ a waste of time 浪费时间。\n顺带记:节省 = save;赚取 = earn;收集 = collect."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"\"I am fond of ___ books.\"(介词 of + 动名词:读)","options":["reading","to read","read","reads"],"answer_index":0,"stem_cn":"我喜欢读书。","explanation_cn":"介词 of 后面用动名词,be fond of reading = 喜欢读书。✓ I am fond of reading books."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"\"___ early is good for your health.\"(动名词作主语:早起)","options":["Gets up","Get up","Got up","Getting up"],"answer_index":3,"stem_cn":"早起有益健康。","explanation_cn":"\"早起\"作主语,用动名词 Getting up。✓ Getting up early is good for your health."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"\"It''s a waste of time.\" 这句话的意思是:","options":["这很省时间。","这要花很多钱。","这是浪费时间。","这很值得。"],"answer_index":2,"explanation_cn":"It''s a waste of time. 意思是\"这是浪费时间\"。a waste of time = 白费工夫。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"\"You must give up smoking.\" 这句话的意思是:","options":["你必须开始抽烟。","你必须戒烟。","你举起香烟。","你可以随便抽烟。"],"answer_index":1,"explanation_cn":"You must give up smoking. 意思是\"你必须戒烟\"。give up = 放弃、戒掉。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"Why doesn''t the writer worry about catching nothing?","options":["Because he sells the fish later","Because he catches boots instead","Because his friends catch fish for him","Because he only wants to sit in a boat and relax"],"answer_index":3,"passage":"Fishing is my favorite sport. I often fish for hours without catching anything. But this does not worry me. Some fishermen are unlucky. Instead of catching fish, they catch old boots and trash. I am even less lucky. I never catch anything — not even old boots. After having spent whole mornings on the river, I always go home with an empty bag. ''You must give up fishing!'' my friends say. ''It''s a waste of time.'' But they don''t realize one important thing. I''m not really interested in fishing. I am only interested in sitting in a boat and doing nothing at all!","explanation_cn":"课文说他真正想要的只是独坐孤舟、什么也不干,所以钓不到鱼也不烦恼。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"What do some unlucky fishermen catch instead of fish?","options":["Old boots and trash","Nothing at all","Gold coins","Big sharks"],"answer_index":0,"passage":"Fishing is my favorite sport. I often fish for hours without catching anything. But this does not worry me. Some fishermen are unlucky. Instead of catching fish, they catch old boots and trash. I am even less lucky. I never catch anything — not even old boots. After having spent whole mornings on the river, I always go home with an empty bag. ''You must give up fishing!'' my friends say. ''It''s a waste of time.'' But they don''t realize one important thing. I''m not really interested in fishing. I am only interested in sitting in a boat and doing nothing at all!","explanation_cn":"课文说 they catch old boots and trash,倒霉的钓鱼人钓上来的是旧靴子和垃圾。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"What do the writer''s friends tell him to do?","options":["Catch more boots","Buy a bigger boat","Give up fishing","Fish in the sea"],"answer_index":2,"audio":"Fishing is my favorite sport. I often fish for hours without catching anything. But this does not worry me. Some fishermen are unlucky. Instead of catching fish, they catch old boots and trash. I am even less lucky. I never catch anything — not even old boots. After having spent whole mornings on the river, I always go home with an empty bag. ''You must give up fishing!'' my friends say. ''It''s a waste of time.'' But they don''t realize one important thing. I''m not really interested in fishing. I am only interested in sitting in a boat and doing nothing at all!","explanation_cn":"课文说 my friends say ''You must give up fishing'',朋友们劝他别再钓鱼。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l20',10,NULL,'choice','{"stem":"Is the writer really interested in fishing?","options":["No, only in sitting in a boat doing nothing","No, he hates the river","Yes, he wants to win a prize","Yes, he loves catching fish"],"answer_index":0,"audio":"Fishing is my favorite sport. I often fish for hours without catching anything. But this does not worry me. Some fishermen are unlucky. Instead of catching fish, they catch old boots and trash. I am even less lucky. I never catch anything — not even old boots. After having spent whole mornings on the river, I always go home with an empty bag. ''You must give up fishing!'' my friends say. ''It''s a waste of time.'' But they don''t realize one important thing. I''m not really interested in fishing. I am only interested in sitting in a boat and doing nothing at all!","explanation_cn":"课文说 I''m not really interested in fishing,他其实对钓鱼没兴趣,只想独坐孤舟。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l21',2,3,21,'Mad or not?','是不是疯了?','被动语态(主考:be + 过去分词表''被…'' · 一般时被动 is/was built · 情态被动 can/must/will + be + 过去分词 · 现在完成被动 has been done · must have been + 过去分词——对过去的被动推测 · by 引出施动者)+ 现在分词作定语 / 本课短语(辅考:passing planes 过往的飞机 · drive sb mad 逼疯 · be determined to 决心)','住在机场附近,过往飞机日夜不绝于耳、快把人逼疯;一百多邻居被噪音赶走,有人出大价钱让我搬走——但我决心留下,大家都说我一定是疯了','{"q":"Listen and answer — Why do people think the writer is mad?","options":["Because he refuses to leave a house near a noisy airport","Because he cannot hear the planes","Because he wants to build an airport","Because he has too much money"],"answer_index":0}'::jsonb,'{"title":"说''某事被…''(被动语态 be + 过去分词)","intro":"本课讲被动语态——主语是动作的承受者(''被…'')。构成:be + 过去分词。跟 can/must/will 一起用时是 can/must/will + be + 过去分词;''肯定已被…了''用 must have been + 过去分词。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["被动 = be + 过去分词(''被…'')","The airport was built years ago."],["can / must / will + be + 过去分词","Passing planes can be heard night and day."],["现在完成的被动:has / have been + 过去分词","I have been offered a large sum of money."],["''肯定已被…了''= must have been + 过去分词","A hundred people must have been driven away."]]},"specialRules":[{"rule":"''被谁做的''用 by 引出:The thieves will be arrested by the police.","mark":"by 施动者"},{"rule":"passing planes:passing 是现在分词作定语,''过往的飞机''","mark":"-ing 作定语"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',1,NULL,'Airplanes are slowly driving me mad.','飞机正在逐渐把我逼疯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',2,NULL,'I live near an airport, and passing planes can be heard night and day.','我住在一个机场附近,过往飞机日夜不绝于耳。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',3,NULL,'The airport was built years ago, but for some reason it could not be used then.','机场是许多年前建的,但由于某种原因当时未能启用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',4,NULL,'Last year, however, it came into use.','然而去年机场开始使用了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',5,NULL,'Over a hundred people must have been driven away from their homes by the noise.','有一百多人肯定是被噪音逼得已经弃家远去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',6,NULL,'Most of my neighbors have already left, and I am one of the few people who stay.','我的大多数邻居都已搬走,我是少数留下来的人中的一个。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',7,NULL,'Sometimes I think this house will be knocked down by a passing plane.','有时我觉得这房子就要被一架飞过的飞机撞倒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',8,NULL,'I have been offered a large sum of money to go away, but I am determined to stay here.','他们曾向我提供一大笔钱让我搬走,但我决定留在这儿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l21',9,NULL,'Everybody says I must be mad, and they are probably right.','大家都说我肯定是疯了,也许他们说的是对的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
