INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l21','drive sb mad','',NULL,'/draɪv ˈsʌmbədi mæd/','Airplanes are driving me mad.','飞机正把我逼疯。','The noise drives me mad.','这噪音快把我逼疯了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l21','come into use','',NULL,'/kʌm ˈɪntə juːs/','Last year it came into use.','去年它开始启用。','The new bridge came into use in May.','新桥五月启用。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l21','be determined to','',NULL,'/bi dɪˈtɜːrmɪnd tə/','I am determined to stay here.','我决心留在这儿。','She is determined to win.','她决心要赢。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l21','a sum of money','',NULL,'/ə sʌm əv ˈmʌni/','I was offered a large sum of money.','有人给我一大笔钱。','He saved a large sum of money.','他存了一大笔钱。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp1','choice','{"stem":"被动语态(be + 过去分词)表示什么?","options":["动作将来才发生","动作正在进行","主语是动作的承受者(被…)","主语主动去做某事"],"answer_index":2,"explanation_cn":"被动语态里,主语是动作的承受者,表示\"被…、受…\"。✓ The airport was built = 机场被建。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp1','choice','{"stem":"被动语态的基本构成是:","options":["have + 过去分词","be + 动词-ing","will + 动词原形","be + 过去分词"],"answer_index":3,"explanation_cn":"被动语态的基本构成 = be + 过去分词。✓ is / was + done。be 随时态和人称变化。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp2','choice','{"stem":"\"The airport ___ built years ago.\"(过去被动:被建造)","options":["is","was","does","has"],"answer_index":1,"stem_cn":"机场是许多年前建的。","explanation_cn":"\"机场被建\"是过去被动,用 was + 过去分词 built。✓ The airport was built years ago."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp2','choice','{"stem":"\"This room ___ cleaned every day.\"(一般现在被动:被打扫)","options":["is","are","has","does"],"answer_index":0,"stem_cn":"这个房间每天都打扫。","explanation_cn":"\"房间每天被打扫\"是现在被动,用 is + 过去分词 cleaned。✓ This room is cleaned every day."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp2','choice','{"stem":"\"English ___ spoken here.\"(一般现在被动:被说)","options":["are","does","has","is"],"answer_index":3,"stem_cn":"这里说英语。","explanation_cn":"\"这里说英语\"其实是\"英语被说\",现在被动用 is spoken。✓ English is spoken here."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp3','choice','{"stem":"情态动词(can/must/will)后面变被动,用:","options":["情态动词 + have + 过去分词","情态动词 + be + 过去分词","情态动词 + being + 过去分词","情态动词 + 过去分词"],"answer_index":1,"explanation_cn":"can / must / will 后面变被动,用\"情态动词 + be + 过去分词\"。✓ can be done, must be tested."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp3','choice','{"stem":"\"Passing planes can ___ heard.\"(情态被动:能被听到)","options":["be","being","been","are"],"answer_index":0,"stem_cn":"过往的飞机日夜可闻。","explanation_cn":"can 后面变被动用 can be + 过去分词,\"能被听到\"= can be heard。✓ Passing planes can be heard."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp3','choice','{"stem":"\"This letter must ___ written again.\"(情态被动:必须被重写)","options":["been","be","is","being"],"answer_index":1,"stem_cn":"这封信必须重写。","explanation_cn":"must 后面变被动用 must be + 过去分词,\"必须被重写\"= must be written。✓ This letter must be written again."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp4','choice','{"stem":"\"My bag has ___ stolen.\"(现在完成被动:已被偷)","options":["was","be","being","been"],"answer_index":3,"stem_cn":"我的包被偷了。","explanation_cn":"现在完成被动 = has / have been + 过去分词,\"已被偷\"= has been stolen。✓ My bag has been stolen."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp4','choice','{"stem":"现在完成时的被动语态是:","options":["has/have been + 过去分词","is/are + 过去分词","will be + 过去分词","has/have + 过去分词"],"answer_index":0,"explanation_cn":"现在完成时的被动语态 = has / have been + 过去分词。✓ It has been done."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp5','choice','{"stem":"\"肯定已经被…了\"(对过去的被动推测)用:","options":["must have + 过去分词","must have been + 过去分词","must be + 过去分词","must + 过去分词"],"answer_index":1,"explanation_cn":"\"肯定已经被…了\"(对过去的被动推测)= must have been + 过去分词。✓ It must have been stolen."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp5','choice','{"stem":"\"Over a hundred people must ___ been driven away.\"(对过去的被动推测)","options":["be","has","had","have"],"answer_index":3,"stem_cn":"肯定有一百多人被赶走了。","explanation_cn":"\"肯定被赶走了\"是对过去的被动推测,用 must have been driven(这里填 have)。✓ People must have been driven away."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp5','choice','{"stem":"\"My bag is gone; it must have ___ stolen.\"(肯定已被偷)","options":["been","being","was","be"],"answer_index":0,"stem_cn":"我的包不见了,肯定是被偷了。","explanation_cn":"\"肯定被偷了\"用 must have been stolen(这里填 been)。✓ It must have been stolen."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp6','choice','{"stem":"主动句 \"The police will arrest the thieves\" 变被动是:","options":["The thieves will arrest the police.","The thieves will be arrested by the police.","The thieves arrested the police.","The police will be arrested by the thieves."],"answer_index":1,"explanation_cn":"主动 The police will arrest the thieves,变被动把 the thieves 提到前面:will be arrested,施动者用 by the police。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp6','choice','{"stem":"被动句里,\"被谁做的\"用哪个词引出?","options":["by","with","of","for"],"answer_index":0,"explanation_cn":"被动句里\"被谁做的\"用 by 引出。✓ arrested by the police."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp7','choice','{"stem":"\"passing planes\" 里的 passing 是:","options":["一个名词","过去分词","动词谓语","现在分词作定语(过往的飞机)"],"answer_index":3,"explanation_cn":"passing 是现在分词,放名词前作定语,passing planes = 过往(正飞过)的飞机。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp7','choice','{"stem":"\"a sleeping baby\" 里的 sleeping 修饰 baby,意思是:","options":["睡眠这件事","正在睡觉的婴儿","婴儿在睡这个动作","被睡着的婴儿"],"answer_index":1,"explanation_cn":"sleeping 是现在分词作定语,a sleeping baby = 正在睡觉的婴儿。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',5,'am2_l21_gp8','choice','{"stem":"drive sb mad 的意思是:","options":["让某人开车","开车送某人","把某人逼疯","使某人高兴"],"answer_index":2,"explanation_cn":"drive sb mad = 把某人逼疯、弄得发狂。✓ Airplanes are driving me mad."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"美语\"飞机\"拼作:","options":["areoplane","airplaine","aeroplane","airplane"],"answer_index":3,"explanation_cn":"美语\"飞机\"拼 airplane;英式拼 aeroplane。✓ Airplanes are loud."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"美语\"邻居\"拼作:","options":["naybor","neighbor","neighbour","neighber"],"answer_index":1,"explanation_cn":"美语\"邻居\"拼 neighbor;英式拼 neighbour。✓ my neighbor next door."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"drive sb mad 的意思是:","options":["把某人逼疯","开车送某人","让某人生病","使某人开心"],"answer_index":0,"explanation_cn":"drive sb mad = 把某人逼疯。✓ The noise drives me mad,噪音快把我逼疯了。\n顺带记:开车送某人 = drive sb somewhere;使某人开心 = make sb happy;让某人生病 = make sb sick."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"come into use 的意思是:","options":["用光了","开始使用,启用","停止使用","很有用"],"answer_index":1,"explanation_cn":"come into use = 开始使用、启用。✓ It came into use last year,它去年启用。\n顺带记:停止使用 = go out of use;很有用 = be useful;用光 = run out."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"be determined to 的意思是:","options":["忘记做…","拒绝做…","决心做…","害怕做…"],"answer_index":2,"explanation_cn":"be determined to = 决心做…。✓ I''m determined to stay,我决心留下。\n顺带记:拒绝做 = refuse to;害怕做 = be afraid to;忘记做 = forget to."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',6,NULL,'choice','{"stem":"a sum of money 的意思是:","options":["一张地图","一堆废纸","一份工作","一笔钱"],"answer_index":3,"explanation_cn":"a sum of money = 一笔钱、一笔款项。✓ a large sum of money 一大笔钱。\n顺带记:一堆废纸 = a pile of paper;一份工作 = a job;一张地图 = a map."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',7,NULL,'cloze','{"stem":"第 1 空","context":"I live near an airport, and passing planes can ___1___ heard all day. The airport ___2___ built years ago, but nobody used it then. Over a hundred people ___3___ driven away by the noise. I ___4___ offered money to leave, but I want to stay.","blank_no":1,"options":["be","are","being","been"],"answer_index":0,"explanation_cn":"can 后面变被动用 can be + 过去分词,\"能被听到\"= can be heard。✓ Passing planes can be heard.\n✗ are:can 后面直接跟原形 be,不跟 are;✗ being:can being 不通;✗ been:been 要跟在 have 后面,不跟 can."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',7,NULL,'cloze','{"stem":"第 2 空","context":"I live near an airport, and passing planes can ___1___ heard all day. The airport ___2___ built years ago, but nobody used it then. Over a hundred people ___3___ driven away by the noise. I ___4___ offered money to leave, but I want to stay.","blank_no":2,"options":["was","is","has","were"],"answer_index":0,"explanation_cn":"\"机场被建\"是过去被动,用 was built。✓ The airport was built years ago.\n✗ is:机场是过去建的,不用现在 is;✗ has:has built 是主动完成,不是被动;✗ were:主语 airport 单数,用 was 不用 were."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',7,NULL,'cloze','{"stem":"第 3 空","context":"I live near an airport, and passing planes can ___1___ heard all day. The airport ___2___ built years ago, but nobody used it then. Over a hundred people ___3___ driven away by the noise. I ___4___ offered money to leave, but I want to stay.","blank_no":3,"options":["must have been","must be","have","are"],"answer_index":0,"explanation_cn":"\"肯定被赶走了\"是对过去的被动推测,用 must have been driven。✓ Over a hundred people must have been driven away.\n✗ must be:must be driven 说的是现在,不是\"已经被\";✗ have:少了 been,构不成被动;✗ are:are driven 是现在被动,和\"肯定已经\"对不上."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',7,NULL,'cloze','{"stem":"第 4 空","context":"I live near an airport, and passing planes can ___1___ heard all day. The airport ___2___ built years ago, but nobody used it then. Over a hundred people ___3___ driven away by the noise. I ___4___ offered money to leave, but I want to stay.","blank_no":4,"options":["have been","have","am","was"],"answer_index":0,"explanation_cn":"\"我被给了钱\"是现在完成被动,用 have been offered。✓ I have been offered money.\n✗ have:少了 been,不是被动;✗ am:am offered 缺 been,时态不对;✗ was:was offered 是过去被动,和后文\"现在想留下\"对不上."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',8,NULL,'choice','{"stem":"Where does the writer live?","options":["Near a train station","In the city center","By the sea","Near an airport"],"answer_index":3,"explanation_cn":"课文说 I live near an airport,作者住在机场附近。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',8,NULL,'choice','{"stem":"Why is the writer slowly going mad?","options":["Because he is sick","Because he has no money","Because of the noise of passing planes","Because he lives all alone"],"answer_index":2,"explanation_cn":"课文说 passing planes can be heard night and day,过往飞机的噪音日夜不停,快把他逼疯。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',8,NULL,'choice','{"stem":"What is the writer determined to do?","options":["To build an airport","To stay in the house","To sell the house","To move to the city"],"answer_index":1,"explanation_cn":"课文说 I am determined to stay here,尽管有人给钱让他搬走,他还是决心留下。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',9,NULL,'choice','{"stem":"你想说\"这块表能修好\"(能被…用 can be + 过去分词):","options":["Your watch can repair.","Your watch can be repaired.","Your watch is can repaired.","Your watch can be repair."],"answer_index":1,"explanation_cn":"\"能被修好\"用 can be + 过去分词 repaired。✓ Your watch can be repaired. 场合:告诉别人东西还能修。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',9,NULL,'choice','{"stem":"你想说\"这封信必须重写\"(必须被…用 must be + 过去分词):","options":["This letter must write again.","This letter must be write again.","This letter is must written again.","This letter must be written again."],"answer_index":3,"explanation_cn":"\"必须被重写\"用 must be + 过去分词 written。✓ This letter must be written again. 场合:要求把信重写一遍。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',9,NULL,'choice','{"stem":"你想说\"小偷会被抓住\"(会被…用 will be + 过去分词):","options":["The thief will catch.","The thief will be catch.","The thief will be caught.","The thief is will caught."],"answer_index":2,"explanation_cn":"\"会被抓住\"用 will be + 过去分词 caught。✓ The thief will be caught. 场合:有信心小偷终将落网。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"determined 的意思是:","options":["害怕的","犹豫的","疲惫的","坚定的,下决心的"],"answer_index":3,"explanation_cn":"determined = 坚定的、下了决心的。✓ I am determined to stay,我决心留下。\n顺带记:犹豫的 = hesitant;疲惫的 = tired;害怕的 = afraid."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"reason 的意思是:","options":["原因","地区","结果","季节"],"answer_index":0,"explanation_cn":"reason = 原因、理由。✓ for some reason 由于某种原因。\n顺带记:结果 = result;季节 = season;地区 = region."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"\"The room ___ cleaned every day.\"(一般现在被动:被打扫)","options":["are","being","has","is"],"answer_index":3,"stem_cn":"这个房间每天都被打扫。","explanation_cn":"\"房间每天被打扫\"是现在被动,用 is + 过去分词 cleaned。✓ The room is cleaned every day."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"\"My bag ___ been stolen.\"(现在完成被动:已被偷)","options":["was","is","has","have"],"answer_index":2,"stem_cn":"我的包被偷了。","explanation_cn":"\"包被偷了\"是现在完成被动,用 has been stolen(这里填 has)。✓ My bag has been stolen."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"\"You must be mad!\" 这句话的意思是:","options":["你必须变疯!","你可能会疯。","你不许发疯!","你一定是疯了!"],"answer_index":3,"explanation_cn":"You must be mad! 这里 must 是\"一定是\"的推测,意思是\"你一定是疯了\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"\"I am determined to stay.\" 这句话的意思是:","options":["我下决心留下来。","我可能会留下来。","我不想留下来。","我被迫留下来。"],"answer_index":0,"explanation_cn":"I am determined to stay. 意思是\"我下决心留下来\"。be determined to = 决心做某事。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"Why couldn''t the airport be used at first?","options":["Because it was closed for repairs","Because it was too small","For some reason it could not be used then","Because there were no planes"],"answer_index":2,"passage":"Airplanes are slowly driving me mad. I live near an airport, and passing planes can be heard night and day. The airport was built years ago, but for some reason it could not be used then. Last year, however, it came into use. Over a hundred people must have been driven away from their homes by the noise. Most of my neighbors have already left, and I am one of the few people who stay. Sometimes I think this house will be knocked down by a passing plane. I have been offered a large sum of money to go away, but I am determined to stay here. Everybody says I must be mad, and they are probably right.","explanation_cn":"课文说 for some reason it could not be used then,由于某种原因机场当时无法启用。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"What has the writer been offered?","options":["A large sum of money to go away","A job at the airport","A quieter apartment","A new house by the sea"],"answer_index":0,"passage":"Airplanes are slowly driving me mad. I live near an airport, and passing planes can be heard night and day. The airport was built years ago, but for some reason it could not be used then. Last year, however, it came into use. Over a hundred people must have been driven away from their homes by the noise. Most of my neighbors have already left, and I am one of the few people who stay. Sometimes I think this house will be knocked down by a passing plane. I have been offered a large sum of money to go away, but I am determined to stay here. Everybody says I must be mad, and they are probably right.","explanation_cn":"课文说 I have been offered a large sum of money to go away,有人出一大笔钱让他搬走。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"What can be heard near the writer''s home night and day?","options":["Passing trains","Loud music","Barking dogs","Passing planes"],"answer_index":3,"audio":"Airplanes are slowly driving me mad. I live near an airport, and passing planes can be heard night and day. The airport was built years ago, but for some reason it could not be used then. Last year, however, it came into use. Over a hundred people must have been driven away from their homes by the noise. Most of my neighbors have already left, and I am one of the few people who stay. Sometimes I think this house will be knocked down by a passing plane. I have been offered a large sum of money to go away, but I am determined to stay here. Everybody says I must be mad, and they are probably right.","explanation_cn":"课文说 passing planes can be heard night and day,日夜能听到的是过往的飞机。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l21',10,NULL,'choice','{"stem":"Does the writer want to leave?","options":["Yes, he leaves tomorrow","Yes, for a lot of money","No, he is determined to stay","No, but he has to go"],"answer_index":2,"audio":"Airplanes are slowly driving me mad. I live near an airport, and passing planes can be heard night and day. The airport was built years ago, but for some reason it could not be used then. Last year, however, it came into use. Over a hundred people must have been driven away from their homes by the noise. Most of my neighbors have already left, and I am one of the few people who stay. Sometimes I think this house will be knocked down by a passing plane. I have been offered a large sum of money to go away, but I am determined to stay here. Everybody says I must be mad, and they are probably right.","explanation_cn":"课文说 I am determined to stay here,他不想走,决心留下。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l22',2,3,22,'A glass envelope','玻璃信封','动词 + 介词固定搭配(主考:dream/think/hear + of · receive/suffer/borrow + from · believe/succeed/persist + in · depend/rely/insist + on · 介词后接动名词 dream of doing)+ 过去进行时作背景 / throw 不规则动词(辅考:we were traveling…put · throw-threw-thrown)','女儿简把写着姓名地址的纸条塞进瓶子扔进大海;十个月后竟收到荷兰一位同龄姑娘的来信——如今两人定期通信,只是改用了邮寄,虽贵一点却快得多','{"q":"Listen and answer — How did Jane receive a letter from a stranger?","options":["A girl in Holland found the bottle Jane threw into the sea","A friend gave her the letter","She found it in a store","Her teacher mailed it to her"],"answer_index":0}'::jsonb,'{"title":"动词后面跟哪个介词(of / from / in / on)","intro":"本课讲一批''动词 + 介词''的固定搭配:哪个动词后面跟 of、哪个跟 from、哪个跟 in、哪个跟 on。介词后面接动词时要用动名词。全用本课句子举例。","table":{"headers":["搭配","本课 / 常见例子"],"rows":[["+ of:dream / think / hear / approve of","Jane never dreamed of receiving a letter."],["+ from:receive / suffer / borrow / prevent from","She received a letter from a girl in Holland."],["+ in:believe / succeed / persist / take part in","They believe in writing to each other."],["+ on:depend / rely / insist / congratulate on","Now they depend on the mail."]]},"specialRules":[{"rule":"介词后面接动词用动名词:dream of receiving, think of doing","mark":"介词 + -ing"},{"rule":"throw 是不规则动词:throw – threw – thrown","mark":"不规则动词"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',1,NULL,'My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland.','我的女儿简从未想过会接到荷兰一位同龄姑娘的来信。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',2,NULL,'Last year, we were traveling across the English Channel, and Jane put a piece of paper with her name and address on it into a bottle.','去年,当我们横渡英吉利海峡时,简把写有她姓名和住址的一张纸条装进了一只瓶子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',3,NULL,'She threw the bottle into the sea.','又将瓶子扔进了大海。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',4,NULL,'She never thought of it again, but ten months later, she received a letter from a girl in Holland.','此后她就再没去想那只瓶子。但十个月以后,她收到了荷兰一位姑娘的来信。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',5,NULL,'The two girls write to each other regularly now.','现在这两位姑娘定期通信了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',6,NULL,'However, they have decided to use the mail.','然而她们还是决定利用邮寄。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l22',7,NULL,'Letters will cost a little more, but they will certainly travel faster.','这样会稍微多花点钱,但肯定是快得多了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
