INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l22','dream of','',NULL,'/driːm əv/','Jane never dreamed of receiving a letter.','简从没想过会收到一封信。','I dream of becoming a doctor.','我梦想成为一名医生。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l22','think of','',NULL,'/θɪŋk əv/','She never thought of it again.','她再没想起那只瓶子。','What do you think of this idea?','你觉得这个主意怎么样?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l22','receive from','',NULL,'/rɪˈsiːv frəm/','She received a letter from a girl in Holland.','她收到荷兰一位姑娘的来信。','I received a gift from my aunt.','我收到姑姑送的礼物。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l22','write to','',NULL,'/raɪt tə/','The two girls write to each other.','两个姑娘互相写信。','Please write to me soon.','请尽快给我写信。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp1','choice','{"stem":"dream(梦想)后面通常接哪个介词?","options":["of","in","at","from"],"answer_index":0,"explanation_cn":"dream(梦想、想到)后面接介词 of。✓ dream of receiving a letter."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp1','choice','{"stem":"\"Jane never dreamed ___ receiving a letter.\"(梦想到、想到)","options":["in","on","from","of"],"answer_index":3,"stem_cn":"简从没想过会收到一封信。","explanation_cn":"\"想到会收到信\"用 dream of + 动名词。✓ Jane never dreamed of receiving a letter. from / in / on 都不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp2','choice','{"stem":"receive / suffer / borrow 后面常接哪个介词?","options":["on","from","in","of"],"answer_index":1,"explanation_cn":"receive / suffer / borrow 后面接 from。✓ receive a letter from someone."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp2','choice','{"stem":"\"She received a letter ___ a girl in Holland.\"(收到…的来信)","options":["of","on","from","in"],"answer_index":2,"stem_cn":"她收到了荷兰一位姑娘的来信。","explanation_cn":"\"收到某人的来信\"用 receive a letter from。✓ She received a letter from a girl in Holland."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp3','choice','{"stem":"believe / succeed / persist 后面常接哪个介词?","options":["from","on","of","in"],"answer_index":3,"explanation_cn":"believe / succeed / persist 后面接 in。✓ believe in, succeed in."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp3','choice','{"stem":"\"They believe ___ writing to each other.\"(信奉、坚持)","options":["in","on","of","from"],"answer_index":0,"stem_cn":"她们相信要常常互相写信。","explanation_cn":"\"相信、坚持要做某事\"用 believe in + 动名词。✓ They believe in writing to each other."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp4','choice','{"stem":"depend / rely / insist 后面常接哪个介词?","options":["of","on","from","in"],"answer_index":1,"explanation_cn":"depend / rely / insist 后面接 on。✓ depend on, rely on, insist on."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp4','choice','{"stem":"\"It all depends ___ the weather.\"(取决于、全看)","options":["on","in","of","from"],"answer_index":0,"stem_cn":"这全看天气。","explanation_cn":"\"取决于、全看\"用 depend on。✓ It all depends on the weather."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp4','choice','{"stem":"\"He congratulated me ___ my success.\"(祝贺)","options":["of","from","in","on"],"answer_index":3,"stem_cn":"他祝贺我成功。","explanation_cn":"\"祝贺某人某事\"用 congratulate sb on。✓ He congratulated me on my success."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp5','choice','{"stem":"介词(of / in / on…)后面接动词时,要用:","options":["动词原形","不定式 to do","动名词(-ing)","过去式"],"answer_index":2,"explanation_cn":"介词后面接动词时,一律用动名词。✓ dream of receiving, interested in collecting."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp5','choice','{"stem":"\"I dream of ___ a pilot.\"(dream of + 动名词:成为)","options":["becoming","become","became","to become"],"answer_index":0,"stem_cn":"我梦想成为一名飞行员。","explanation_cn":"dream of 后面接动名词,\"梦想成为\"= dream of becoming。✓ I dream of becoming a pilot."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp5','choice','{"stem":"\"She is interested in ___ stamps.\"(对…感兴趣:收集)","options":["collect","collected","collecting","to collect"],"answer_index":2,"stem_cn":"她喜欢集邮。","explanation_cn":"be interested in 后面接动名词,\"喜欢收集\"= interested in collecting。✓ She is interested in collecting stamps."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp6','choice','{"stem":"\"The medicine saved him ___ death.\"(救他免于)","options":["on","from","in","of"],"answer_index":1,"stem_cn":"那药救了他一命。","explanation_cn":"save sb from = 使某人免于…。✓ The medicine saved him from death."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp6','choice','{"stem":"\"Success depends ___ hard work.\"(靠、取决于)","options":["on","from","of","in"],"answer_index":0,"stem_cn":"成功靠努力。","explanation_cn":"\"成功取决于努力\"用 depend on。✓ Success depends on hard work."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp7','choice','{"stem":"\"We ___ traveling when Jane threw the bottle.\"(过去进行时作背景:正在旅行)","options":["did","have","were","are"],"answer_index":2,"stem_cn":"简扔瓶子时,我们正在旅行途中。","explanation_cn":"\"正在旅行\"是过去进行时,主语 we 用 were + 动词-ing。✓ We were traveling when Jane threw the bottle."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp7','choice','{"stem":"过去进行时(was/were + 动词-ing)在故事里常用来:","options":["表示一件被动的事","表示反复的习惯","表示将来的计划","描述当时正在进行的背景"],"answer_index":3,"explanation_cn":"过去进行时(was/were + 动词-ing)在故事里常用来描述当时正在进行的背景,再引出新动作。✓ We were traveling when she threw the bottle."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp8','choice','{"stem":"throw 的过去式和过去分词是:","options":["threw / thrown","throwed / throwed","threw / threw","thrown / threw"],"answer_index":0,"explanation_cn":"throw 是不规则动词:throw – threw – thrown。别写成 throwed。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',5,'am2_l22_gp8','choice','{"stem":"\"She ___ the bottle into the sea.\"(throw 的过去式:扔)","options":["throws","threw","throwed","thrown"],"answer_index":1,"stem_cn":"她把瓶子扔进了大海。","explanation_cn":"\"扔\"的过去式是 threw(不规则)。✓ She threw the bottle into the sea. 别写成 throwed。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"美语\"旅行/行进\"拼作:","options":["travling","travelin","travelling","traveling"],"answer_index":3,"explanation_cn":"美语\"旅行/行进\"单写一个 l:traveling / traveled;英式双写:travelling / travelled。✓ traveling across the sea."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"美语\"邮件/邮寄\"常说:","options":["post","mail","sending","letter box"],"answer_index":1,"explanation_cn":"美语\"邮件、邮寄\"常说 mail;英式说 post。✓ use the mail 用邮寄。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"dream of 的意思是:","options":["梦想;想到","厌倦","属于","害怕"],"answer_index":0,"explanation_cn":"dream of = 梦想、想到。✓ dream of receiving a letter 想到会收到信。\n顺带记:害怕 = be afraid of;厌倦 = be tired of;属于 = belong to."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"receive a letter from 的意思是:","options":["拒收…的信","给…写信","把信寄给…","收到…的来信"],"answer_index":3,"explanation_cn":"receive a letter from = 收到…的来信。✓ a letter from a girl 一位姑娘的来信。\n顺带记:给…写信 = write to;把信寄给… = send a letter to;拒收 = refuse to accept."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"think of 的意思是:","options":["同意","包含","想起;考虑","逃离"],"answer_index":2,"explanation_cn":"think of = 想起、考虑。✓ She never thought of it again 她再没想起它。\n顺带记:同意 = agree with;逃离 = escape from;包含 = consist of."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',6,NULL,'choice','{"stem":"regularly 的意思是:","options":["突然地","定期地,经常","从不","偶尔地"],"answer_index":1,"explanation_cn":"regularly = 定期地、经常。✓ write regularly 定期通信。\n顺带记:偶尔 = sometimes;从不 = never;突然 = suddenly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',7,NULL,'cloze','{"stem":"第 1 空","context":"Jane never dreamed ___1___ getting a letter one day. Months later she received a nice letter ___2___ a stranger. The two girls now believe ___3___ writing often, and they depend ___4___ the mail to stay close.","blank_no":1,"options":["of","from","in","on"],"answer_index":0,"explanation_cn":"dream 后面接 of,\"想到会收到信\"= dreamed of getting。✓ Jane never dreamed of getting a letter.\n✗ from:dream 不接 from;✗ in:dream 不接 in;✗ on:dream 不接 on."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',7,NULL,'cloze','{"stem":"第 2 空","context":"Jane never dreamed ___1___ getting a letter one day. Months later she received a nice letter ___2___ a stranger. The two girls now believe ___3___ writing often, and they depend ___4___ the mail to stay close.","blank_no":2,"options":["from","of","in","on"],"answer_index":0,"explanation_cn":"receive a letter 后面接 from 引出来信的人。✓ received a letter from a stranger.\n✗ of:receive 不接 of;✗ in:receive 不接 in;✗ on:receive 不接 on."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',7,NULL,'cloze','{"stem":"第 3 空","context":"Jane never dreamed ___1___ getting a letter one day. Months later she received a nice letter ___2___ a stranger. The two girls now believe ___3___ writing often, and they depend ___4___ the mail to stay close.","blank_no":3,"options":["in","of","from","on"],"answer_index":0,"explanation_cn":"believe 后面接 in,\"相信要常写信\"= believe in writing。✓ They believe in writing often.\n✗ of:believe 表\"信奉\"时接 in,不接 of;✗ from:believe 不接 from;✗ on:believe 不接 on."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',7,NULL,'cloze','{"stem":"第 4 空","context":"Jane never dreamed ___1___ getting a letter one day. Months later she received a nice letter ___2___ a stranger. The two girls now believe ___3___ writing often, and they depend ___4___ the mail to stay close.","blank_no":4,"options":["on","of","from","in"],"answer_index":0,"explanation_cn":"depend 后面接 on,\"靠邮寄\"= depend on the mail。✓ They depend on the mail.\n✗ of:depend 不接 of;✗ from:depend 不接 from;✗ in:depend 不接 in."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',8,NULL,'choice','{"stem":"Where did Jane''s letter come from?","options":["From a girl in Holland","From the post office","From a boy in France","From Jane''s teacher"],"answer_index":0,"explanation_cn":"课文说 she received a letter from a girl in Holland,来信是荷兰一位姑娘写的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',8,NULL,'choice','{"stem":"What did Jane put into the bottle?","options":["Some money","A small toy","A photo of herself","A piece of paper with her name and address"],"answer_index":3,"explanation_cn":"课文说 Jane put a piece of paper with her name and address into a bottle,她把写着姓名地址的纸条放进瓶子。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',8,NULL,'choice','{"stem":"How do the two girls send letters now?","options":["In bottles","They don''t write anymore","By mail","By flying there themselves"],"answer_index":2,"explanation_cn":"课文说 they have decided to use the mail,现在两个姑娘改用邮寄。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',9,NULL,'choice','{"stem":"你想说\"我梦想成为一名医生\"(dream of + 动名词):","options":["I dream to become a doctor.","I dream of becoming a doctor.","I dream becoming a doctor.","I dream of become a doctor."],"answer_index":1,"explanation_cn":"dream of 后面接动名词 becoming,\"梦想成为医生\"。✓ I dream of becoming a doctor. 场合:说自己的理想。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',9,NULL,'choice','{"stem":"你想说\"我收到了朋友的来信\"(receive a letter from):","options":["I received a letter to my friend.","I received a letter by my friend.","I received a letter of my friend.","I received a letter from my friend."],"answer_index":3,"explanation_cn":"\"收到朋友的来信\"用 receive a letter from。✓ I received a letter from my friend. 场合:告诉别人收到了谁的信。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',9,NULL,'choice','{"stem":"你想说\"这取决于天气\"(depend on):","options":["It depends on the weather.","It depends to the weather.","It depends of the weather.","It depends in the weather."],"answer_index":0,"explanation_cn":"\"取决于天气\"用 depend on。✓ It depends on the weather. 场合:计划要看天气再定时说。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"throw 的意思是:","options":["购买","推动","接住","扔,抛"],"answer_index":3,"explanation_cn":"throw = 扔、抛(过去式 threw)。✓ She threw the bottle into the sea.\n顺带记:接住 = catch;购买 = buy;推动 = push."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"receive 的意思是:","options":["撕碎","寄出","收到","阅读"],"answer_index":2,"explanation_cn":"receive = 收到、接到。✓ receive a letter 收到一封信。\n顺带记:寄出 = send;撕碎 = tear up;阅读 = read."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"\"He insisted ___ paying the bill.\"(坚持要)","options":["of","in","from","on"],"answer_index":3,"stem_cn":"他坚持要付账。","explanation_cn":"insist 后面接 on,\"坚持要付账\"= insist on paying。✓ He insisted on paying the bill."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"\"This cake consists ___ eggs and flour.\"(由…组成)","options":["in","from","of","on"],"answer_index":2,"stem_cn":"这蛋糕由鸡蛋和面粉做成。","explanation_cn":"consist 后面接 of,\"由…组成\"= consist of。✓ This cake consists of eggs and flour."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"\"It depends on you.\" 这句话的意思是:","options":["这属于你。","这取决于你。","这靠不住。","这与你无关。"],"answer_index":1,"explanation_cn":"It depends on you. 意思是\"这取决于你、由你决定\"。depend on = 取决于。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"\"I dream of traveling the world.\" 这句话的意思是:","options":["我梦想周游世界。","我讨厌旅行。","我正在环游世界。","我昨晚梦见了世界地图。"],"answer_index":0,"explanation_cn":"I dream of traveling the world. 意思是\"我梦想周游世界\"。dream of = 梦想。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"How did Jane''s friendship with the Holland girl begin?","options":["They were in the same class","She threw a bottle with her address into the sea","A teacher introduced them","They met on a boat"],"answer_index":1,"passage":"My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland. Last year, we were traveling across the English Channel, and Jane put a piece of paper with her name and address on it into a bottle. She threw the bottle into the sea. She never thought of it again, but ten months later, she received a letter from a girl in Holland. The two girls write to each other regularly now. However, they have decided to use the mail. Letters will cost a little more, but they will certainly travel faster.","explanation_cn":"课文说简把写有地址的纸条放进瓶子扔进大海,后来荷兰姑娘捡到就通了信。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"Why did the two girls decide to use the mail?","options":["Because letters travel faster than bottles","Because the sea was too rough","Because they lost the bottle","Because bottles are cheaper"],"answer_index":0,"passage":"My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland. Last year, we were traveling across the English Channel, and Jane put a piece of paper with her name and address on it into a bottle. She threw the bottle into the sea. She never thought of it again, but ten months later, she received a letter from a girl in Holland. The two girls write to each other regularly now. However, they have decided to use the mail. Letters will cost a little more, but they will certainly travel faster.","explanation_cn":"课文说 letters will cost a little more, but they will travel faster,信件贵点却快得多,所以改用邮寄。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"How did Jane receive a letter from a stranger?","options":["Her father gave it to her","She wrote to a pen-pal club","A girl in Holland found her bottle","She found it in the mailbox by chance"],"answer_index":2,"audio":"My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland. Last year, we were traveling across the English Channel, and Jane put a piece of paper with her name and address on it into a bottle. She threw the bottle into the sea. She never thought of it again, but ten months later, she received a letter from a girl in Holland. The two girls write to each other regularly now. However, they have decided to use the mail. Letters will cost a little more, but they will certainly travel faster.","explanation_cn":"简把瓶子扔进海里,荷兰一位姑娘捡到,于是给她写了信。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l22',10,NULL,'choice','{"stem":"Do the girls still send letters in bottles?","options":["No, they use the mail now","Yes, but only in summer","Yes, every month","No, they stopped writing"],"answer_index":0,"audio":"My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland. Last year, we were traveling across the English Channel, and Jane put a piece of paper with her name and address on it into a bottle. She threw the bottle into the sea. She never thought of it again, but ten months later, she received a letter from a girl in Holland. The two girls write to each other regularly now. However, they have decided to use the mail. Letters will cost a little more, but they will certainly travel faster.","explanation_cn":"课文说 they have decided to use the mail,她们现在改用邮寄,不再用瓶子。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
